// src/data/book5a-content.js

  export var book5a_texts = {
"5.01": [
  { t: "爱的细节 · Details of Love", lines: [
    { sp: "", zh: "电台要选出一对最恩爱的夫妻。", py: "Diàntái yào xuǎnchū yí duì zuì ēn'ài de fūqī.", ru: "Радиостанция решила выбрать самую любящую супружескую пару." },
    { sp: "", zh: "对比后，有三对夫妻入围。", py: "Duìbǐ hòu, yǒu sān duì fūqī rùwéi.", ru: "После сравнения в финал вышли три пары." },
    { sp: "", zh: "评委叫第一对夫妻说说他俩是如何恩爱的。", py: "Píngwěi jiào dì-yī duì fūqī shuōshuo tā liǎ shì rúhé ēn'ài de.", ru: "Судьи попросили первую пару рассказать, в чём же их любовь друг к другу." },
    { sp: "", zh: "妻子说，前几年她全身瘫痪了，医生说她站起来的可能性很小。", py: "Qīzi shuō, qián jǐ nián tā quánshēn tānhuàn le, yīshēng shuō tā zhàn qǐlai de kěnéngxìng hěn xiǎo.", ru: "Жена рассказала: несколько лет назад она была полностью парализована, и врач сказал, что шансы на то, что она снова встанет, очень малы." },
    { sp: "", zh: "别人都觉得她的丈夫会跟她离婚，她也想过要自杀。", py: "Biérén dōu juéde tā de zhàngfu huì gēn tā líhūn, tā yě xiǎngguo yào zìshā.", ru: "Все думали, что муж разведётся с ней, да и она сама подумывала покончить с собой." },
    { sp: "", zh: "但丈夫一直鼓励她，为她不知找了多少家医院，并且几年如一日地照顾她，从不抱怨。", py: "Dàn zhàngfu yìzhí gǔlì tā, wèi tā bùzhī zhǎole duōshao jiā yīyuàn, bìngqiě jǐ nián rú yí rì de zhàogù tā, cóng bù bàoyuàn.", ru: "Но муж всё время подбадривал её, обошёл ради неё бесчисленное множество больниц и год за годом, изо дня в день, ухаживал за ней, ни разу не пожаловавшись." },
    { sp: "", zh: "在丈夫的爱护和努力下，她终于又站了起来。", py: "Zài zhàngfu de àihù hé nǔlì xià, tā zhōngyú yòu zhànle qǐlai.", ru: "Благодаря заботе и стараниям мужа она наконец снова встала на ноги." },
    { sp: "", zh: "她的故事十分感人，评委们听了都很感动。", py: "Tā de gùshi shífēn gǎnrén, píngwěimen tīngle dōu hěn gǎndòng.", ru: "Её история была очень трогательной, и все судьи, услышав её, были растроганы." },
    { sp: "", zh: "随后进来的是第二对夫妻，他俩说，十几年的婚姻生活中，他们从来没为任何事红过脸、吵过架，一直相亲相爱、相敬如宾。", py: "Suíhòu jìnlai de shì dì-èr duì fūqī, tā liǎ shuō, shí jǐ nián de hūnyīn shēnghuó zhōng, tāmen cónglái méi wèi rènhé shì hóngguo liǎn, chǎoguo jià, yìzhí xiāngqīn-xiāng'ài, xiāngjìng-rúbīn.", ru: "Следом вошла вторая пара: они рассказали, что за больше чем десять лет совместной жизни ни разу ни из-за чего не повышали друг на друга голос и не ссорились — всегда любили друг друга и относились друг к другу с уважением, как к дорогому гостю." },
    { sp: "", zh: "评委们听了暗暗点头。", py: "Píngwěimen tīngle àn'àn diǎntóu.", ru: "Судьи, выслушав, украдкой закивали." },
    { sp: "", zh: "轮到第三对夫妻了，却很长时间不见人。", py: "Lún dào dì-sān duì fūqī le, què hěn cháng shíjiān bú jiàn rén.", ru: "Дошла очередь до третьей пары, но её долго не было видно." },
    { sp: "", zh: "评委们等得有些不耐烦，就走出来看个究竟。", py: "Píngwěimen děng de yǒuxiē bú nàifán, jiù zǒu chūlai kàn ge jiūjìng.", ru: "Судьи, устав ждать, немного потеряли терпение и вышли посмотреть, в чём дело." },
    { sp: "", zh: "只见第三对夫妻仍然坐在门口，男人的头靠在女人的肩膀上，睡着了。", py: "Zhǐ jiàn dì-sān duì fūqī réngrán zuò zài ménkǒu, nánrén de tóu kào zài nǚrén de jiānbǎng shang, shuìzháo le.", ru: "Они увидели, что третья пара всё ещё сидит у двери: голова мужчины лежала на плече женщины — он спал." },
    { sp: "", zh: "一个评委要上前喊醒那个男的，女的却伸出手指做了个小声的动作，然后小心地从包里拿出纸笔，用左手歪歪扭扭写下一行字递给评委，而她的右肩一直让丈夫的脑袋靠着。", py: "Yí ge píngwěi yào shàngqián hǎnxǐng nàge nán de, nǚ de què shēnchū shǒuzhǐ zuòle ge xiǎoshēng de dòngzuò, ránhòu xiǎoxīn de cóng bāo li náchū zhǐ bǐ, yòng zuǒshǒu wāiwāiniǔniǔ xiěxià yì háng zì dì gěi píngwěi, ér tā de yòu jiān yìzhí ràng zhàngfu de nǎodai kàozhe.", ru: "Один из судей хотел подойти и разбудить мужчину, но женщина вытянула палец, показывая жест «тише», затем осторожно достала из сумки бумагу и ручку и левой рукой, неровным почерком, написала строчку и передала судье — при этом её правое плечо всё так же служило опорой для головы мужа." },
    { sp: "", zh: "评委们看那纸条上面写着：", py: "Píngwěimen kàn nà zhǐtiáo shàngmiàn xiězhe:", ru: "Судьи увидели, что на записке было написано:" },
    { sp: "妻子", zh: "别出声，他昨晚没睡好。", py: "Bié chūshēng, tā zuówǎn méi shuì hǎo.", ru: "Не шумите, он вчера ночью плохо спал." },
    { sp: "", zh: "一个评委提起笔在后面续写了一句话：", py: "Yí ge píngwěi tíqǐ bǐ zài hòumiàn xùxiěle yí jù huà:", ru: "Один из судей взял ручку и дописал внизу ещё одну фразу:" },
    { sp: "评委", zh: "但是女士，我们得听你们夫妻俩的叙述啊！", py: "Dànshì nǚshì, wǒmen děi tīng nǐmen fūqī liǎ de xùshù a!", ru: "Но, госпожа, нам всё же нужно услышать рассказ вас обоих!" },
    { sp: "", zh: "女人又写：", py: "Nǚrén yòu xiě:", ru: "Женщина снова написала:" },
    { sp: "妻子", zh: "那我们就不参加了。", py: "Nà wǒmen jiù bù cānjiā le.", ru: "Тогда мы просто не будем участвовать." },
    { sp: "", zh: "大家很吃惊，这个女人为了不影响丈夫睡觉，居然放弃这次机会！", py: "Dàjiā hěn chījīng, zhège nǚrén wèile bù yǐngxiǎng zhàngfu shuìjiào, jūrán fàngqì zhè cì jīhuì!", ru: "Все были поражены: эта женщина, чтобы не мешать мужу спать, неожиданно отказалась от такого шанса!" },
    { sp: "", zh: "但评委们还是决定先不催他们，而是再等待一段时间。", py: "Dàn píngwěimen háishi juédìng xiān bù cuī tāmen, ér shì zài děngdài yí duàn shíjiān.", ru: "Но судьи всё же решили пока не торопить их, а немного подождать." },
    { sp: "", zh: "过了一会儿，男人醒了。", py: "Guòle yíhuìr, nánrén xǐng le.", ru: "Через некоторое время мужчина проснулся." },
    { sp: "", zh: "评委们问他怎么那么累。", py: "Píngwěimen wèn tā zěnme nàme lèi.", ru: "Судьи спросили его, почему он так устал." },
    { sp: "", zh: "男人不好意思地笑笑说：", py: "Nánrén bù hǎoyìsi de xiàoxiao shuō:", ru: "Мужчина смущённо улыбнулся и сказал:" },
    { sp: "丈夫", zh: "我家住一楼，蚊子多。", py: "Wǒ jiā zhù yī lóu, wénzi duō.", ru: "Мы живём на первом этаже, комаров много." },
    { sp: "丈夫", zh: "昨晚半夜我被蚊子叮醒了，我怕我老婆再被吵醒，所以后半夜就在为她赶蚊子。", py: "Zuówǎn bànyè wǒ bèi wénzi dīngxǐng le, wǒ pà wǒ lǎopo zài bèi chǎoxǐng, suǒyǐ hòu bànyè jiù zài wèi tā gǎn wénzi.", ru: "Вчера в полночь меня разбудил комариный укус, я побоялся, что мою жену снова разбудят комары, поэтому вторую половину ночи отгонял их от неё." },
    { sp: "", zh: "最后的结果是，电台增加了两项奖项，将第一对夫妻评为“患难与共夫妻”，将第二对夫妻评为“相敬如宾夫妻”，而真正的“最恩爱夫妻”奖，却给了第三对夫妻。", py: "Zuìhòu de jiéguǒ shì, diàntái zēngjiāle liǎng xiàng jiǎngxiàng, jiāng dì-yī duì fūqī píngwéi \"huànnàn-yǔgòng fūqī\", jiāng dì-èr duì fūqī píngwéi \"xiāngjìng-rúbīn fūqī\", ér zhēnzhèng de \"zuì ēn'ài fūqī\" jiǎng, què gěile dì-sān duì fūqī.", ru: "В итоге радиостанция добавила ещё две номинации: первую пару признали «парой, прошедшей через беды и трудности вместе», вторую — «парой, уважающей друг друга, как дорогого гостя», а настоящую премию «самая любящая пара» получила именно третья пара." }
  ] }
],
"5.02": [
  { t: "留串钥匙给父母 · A Bunch of Keys for Our Parents", lines: [
    { sp: "", zh: "父母一辈子住在农村老家，对老屋的感情，就像没断奶的孩子对母亲一样。", py: "Fùmǔ yíbèizi zhù zài nóngcūn lǎojiā, duì lǎo wū de gǎnqíng, jiù xiàng méi duàn nǎi de háizi duì mǔqīn yíyàng.", ru: "Родители всю жизнь прожили в старом доме в деревне, и их привязанность к этому дому была такой же, как у ещё не отнятого от груди младенца к матери." },
    { sp: "", zh: "因此长年以来，父母很少离开老屋，尽管姥姥、舅舅和姑姑都在城里，父母也坚决不在城里住。", py: "Yīncǐ chángnián yǐlái, fùmǔ hěn shǎo líkāi lǎo wū, jǐnguǎn lǎolao, jiùjiu hé gūgu dōu zài chéng li, fùmǔ yě jiānjué bú zài chéng li zhù.", ru: "Поэтому уже много лет родители почти не покидали старый дом: хотя бабушка (по маме), дядя и тётя жили в городе, родители твёрдо отказывались там селиться." },
    { sp: "", zh: "去年，在我和妻子的努力下，我们终于用打工挣的钱，在县里买了一套新房。", py: "Qùnián, zài wǒ hé qīzi de nǔlì xià, wǒmen zhōngyú yòng dǎgōng zhèng de qián, zài xiàn li mǎile yí tào xīn fáng.", ru: "В прошлом году благодаря нашим с женой усилиям мы наконец на деньги, заработанные на подработках, купили новую квартиру в уездном центре." },
    { sp: "", zh: "新房装修完，父母第一次走进新房时，高兴得不得了。", py: "Xīn fáng zhuāngxiū wán, fùmǔ dì-yī cì zǒujìn xīn fáng shí, gāoxìng de bùdéliǎo.", ru: "Когда ремонт закончился и родители впервые вошли в новую квартиру, они были невероятно рады." },
    { sp: "", zh: "妻子提出留一串钥匙给父母，可他们拒绝了。", py: "Qīzi tíchū liú yí chuàn yàoshi gěi fùmǔ, kě tāmen jùjué le.", ru: "Жена предложила оставить родителям связку ключей, но они отказались." },
    { sp: "", zh: "那天，父亲喝醉了，等他醒时，天色已晚。", py: "Nà tiān, fùqin hē zuì le, děng tā xǐng shí, tiānsè yǐ wǎn.", ru: "В тот день отец напился, и когда он проснулся, было уже поздно." },
    { sp: "", zh: "我和妻子强烈留父母在新房住一夜，第二天再回，但他们仍坚持坐上了最后一趟回老家的车。", py: "Wǒ hé qīzi qiángliè liú fùmǔ zài xīn fáng zhù yí yè, dì-èr tiān zài huí, dàn tāmen réng jiānchí zuòshàngle zuìhòu yí tàng huí lǎojiā de chē.", ru: "Мы с женой настойчиво уговаривали родителей переночевать в новой квартире и вернуться на следующий день, но они всё же настояли и сели на последний автобус до родной деревни." },
    { sp: "", zh: "一段时间后，我和妻子又准备去外地打工，新房只能上锁空着。", py: "Yí duàn shíjiān hòu, wǒ hé qīzi yòu zhǔnbèi qù wàidì dǎgōng, xīn fáng zhǐ néng shàng suǒ kōngzhe.", ru: "Через некоторое время мы с женой снова собрались уехать на заработки, и новую квартиру пришлось запереть и оставить пустовать." },
    { sp: "", zh: "临走那天，父亲从老家赶来送我们。", py: "Lín zǒu nà tiān, fùqin cóng lǎojiā gǎnlái sòng wǒmen.", ru: "В день отъезда отец нарочно приехал из деревни, чтобы нас проводить." },
    { sp: "", zh: "父亲悄悄把我拉到一边说：", py: "Fùqin qiāoqiāo bǎ wǒ lā dào yìbiān shuō:", ru: "Отец тихонько отвёл меня в сторону и сказал:" },
    { sp: "父亲", zh: "你妈说了，你还是留一串新房的钥匙给我们，要是我和你妈什么时候想来了，就来住上几天，顺便给你们晒晒被子，打扫打扫卫生。", py: "Nǐ mā shuō le, nǐ háishi liú yí chuàn xīn fáng de yàoshi gěi wǒmen, yàoshi wǒ hé nǐ mā shénme shíhou xiǎng lái le, jiù lái zhùshàng jǐ tiān, shùnbiàn gěi nǐmen shàishai bèizi, dǎsǎo dǎsǎo wèishēng.", ru: "Мама твоя сказала: ты всё же оставь нам связку ключей от новой квартиры — если мы с ней когда-нибудь захотим приехать, поживём пару дней, заодно проветрим вам одеяла и приберёмся немного." },
    { sp: "", zh: "父亲说这话时，轻声细语，还红着脸，像个害羞的孩子。", py: "Fùqin shuō zhè huà shí, qīngshēng-xìyǔ, hái hóngzhe liǎn, xiàng ge hàixiū de háizi.", ru: "Говоря это, отец говорил тихим, мягким голосом и даже покраснел, точно смущённый ребёнок." },
    { sp: "", zh: "转眼又是半年，我们回家时是一个深冬的夜里。", py: "Zhuǎnyǎn yòu shì bàn nián, wǒmen huí jiā shí shì yí ge shēndōng de yè li.", ru: "Не успели оглянуться — прошло ещё полгода; домой мы вернулись глубокой зимней ночью." },
    { sp: "", zh: "下了长途车，儿子被冻得大哭。", py: "Xiàle chángtú chē, érzi bèi dòng de dà kū.", ru: "Сойдя с междугороднего автобуса, сын так замёрз, что расплакался." },
    { sp: "", zh: "我和妻子想象着打开家门满是灰尘、冷冷清清的景象，觉得心里发寒。", py: "Wǒ hé qīzi xiǎngxiàngzhe dǎkāi jiā mén mǎn shì huīchén, lěnglěng-qīngqīng de jǐngxiàng, juéde xīnli fā hán.", ru: "Мы с женой представляли, как откроем дверь, а там всё в пыли и холодной пустоте, и от этой мысли на душе становилось зябко." },
    { sp: "", zh: "来到楼下，抬头一看，却发现自家亮着灯光。", py: "Láidào lóu xià, táitóu yí kàn, què fāxiàn zìjiā liàngzhe dēngguāng.", ru: "Подойдя к дому, мы подняли голову и вдруг увидели, что у нас в окнах горит свет." },
    { sp: "", zh: "上了楼，开门的竟是微笑着的父母，温暖的气息立刻扑面而来：", py: "Shàngle lóu, kāimén de jìng shì wēixiàozhe de fùmǔ, wēnnuǎn de qìxī lìkè pūmiàn ér lái:", ru: "Поднявшись наверх, мы обнаружили, что дверь открыли улыбающиеся родители, и тёплый воздух сразу же дохнул нам в лицо:" },
    { sp: "", zh: "室内打扫得干干净净，暖气开着，水已温热，卧室床上的被子已铺好，厨房里飘来阵阵饭菜香……", py: "Shìnèi dǎsǎo de gāngān-jìngjìng, nuǎnqì kāizhe, shuǐ yǐ wēnrè, wòshì chuáng shang de bèizi yǐ pūhǎo, chúfáng li piāolái zhènzhèn fàncài xiāng…", ru: "В квартире было чисто прибрано, отопление включено, вода уже тёплая, одеяло на кровати в спальне уже расстелено, а с кухни волнами доносился аромат готовящейся еды…" },
    { sp: "", zh: "父亲说：", py: "Fùqin shuō:", ru: "Отец сказал:" },
    { sp: "父亲", zh: "你妈昨天接到电话，知道你们今晚回来，今天来新房忙了一天了。", py: "Nǐ mā zuótiān jiēdào diànhuà, zhīdào nǐmen jīnwǎn huílai, jīntiān lái xīn fáng mángle yì tiān le.", ru: "Мама вчера получила звонок и узнала, что вы сегодня вечером вернётесь, поэтому весь сегодняшний день провозилась в новой квартире." },
    { sp: "", zh: "原来父母要我留下串钥匙，只是为了让我们回来时，能立刻感受到家的温暖！", py: "Yuánlái fùmǔ yào wǒ liúxià chuàn yàoshi, zhǐshì wèile ràng wǒmen huílai shí, néng lìkè gǎnshòudào jiā de wēnnuǎn!", ru: "Оказывается, родители просили меня оставить им связку ключей лишь ради того, чтобы, вернувшись, мы сразу почувствовали тепло дома!" },
    { sp: "", zh: "我鼻子一酸，流下了热泪……", py: "Wǒ bízi yì suān, liúxiàle rèlèi…", ru: "У меня защипало в носу, и я не смог сдержать горячих слёз…" }
  ] }
],
"5.03": [
  { t: "人生有选择，一切可改变 · Having Choices in Life Makes Change Possible", lines: [
    { sp: "", zh: "翟峰和妻子都是铁路工人，工作稳定、待遇不错。", py: "Zháifēng hé qīzi dōu shì tiělù gōngrén, gōngzuò wěndìng, dàiyù búcuò.", ru: "Чжай Фэн и его жена оба были железнодорожниками — работа стабильная, оплата неплохая." },
    { sp: "", zh: "他们有房有车，从不用为生活发愁。", py: "Tāmen yǒu fáng yǒu chē, cóng bú yòng wèi shēnghuó fā chóu.", ru: "У них были квартира и машина, и им никогда не приходилось тревожиться о жизни." },
    { sp: "", zh: "可翟峰却不想一辈子过这样平静的生活。", py: "Kě Zháifēng què bù xiǎng yíbèizi guò zhèyàng píngjìng de shēnghuó.", ru: "Но Чжай Фэн не хотел всю жизнь прожить такой спокойной жизнью." },
    { sp: "", zh: "通过电视，翟峰迷上了帆船，他觉得帆船能带他撞开“世界之门”：", py: "Tōngguò diànshì, Zháifēng míshàngle fānchuán, tā juéde fānchuán néng dài tā zhuàngkāi \"shìjiè zhī mén\":", ru: "Насмотревшись телепередач, Чжай Фэн увлёкся парусным спортом — ему казалось, что парусник способен распахнуть перед ним «дверь в мир»:" },
    { sp: "", zh: "只要有一艘船，就能航行在无边无际的海上，到任何自己想去的地方。", py: "Zhǐyào yǒu yì sōu chuán, jiù néng hángxíng zài wúbiān-wújì de hǎi shang, dào rènhé zìjǐ xiǎng qù de dìfang.", ru: "Стоит иметь лодку — и можно плавать по бескрайнему морю куда угодно." },
    { sp: "", zh: "由于翟峰和妻子没有积蓄，于是卖房卖车，买下了一艘二手船，翟峰叫它“彩虹号”。", py: "Yóuyú Zháifēng hé qīzi méiyǒu jīxù, yúshì mài fáng mài chē, mǎixiàle yì sōu èrshǒu chuán, Zháifēng jiào tā \"Cǎihóng Hào\".", ru: "Поскольку у Чжай Фэна с женой не было накоплений, они продали квартиру и машину и купили подержанную лодку, которую Чжай Фэн назвал «Радуга»." },
    { sp: "", zh: "出发前，翟峰自学了航海知识。", py: "Chūfā qián, Zháifēng zìxuéle hánghǎi zhīshi.", ru: "Перед отплытием Чжай Фэн самостоятельно изучил основы мореходства." },
    { sp: "", zh: "然而，包括翟峰的父母，所有人都觉得，翟峰“疯了”。", py: "Rán'ér, bāokuò Zháifēng de fùmǔ, suǒyǒu rén dōu juéde, Zháifēng \"fēng le\".", ru: "Однако все, включая родителей Чжай Фэна, были уверены, что он «сошёл с ума»." },
    { sp: "", zh: "2012年11月24日，辞了职的翟峰和妻子带着休学的女儿，第一次驾驶帆船出海了。", py: "Èr líng yī èr nián shíyī yuè èrshísì rì, cíle zhí de Zháifēng hé qīzi dàizhe xiūxué de nǚ'ér, dì-yī cì jiàshǐ fānchuán chū hǎi le.", ru: "24 ноября 2012 года уволившийся Чжай Фэн с женой, взяв дочь, оформившую академический отпуск, впервые вышли в море на паруснике." },
    { sp: "", zh: "白天，翟峰和妻子轮流驾船。", py: "Báitiān, Zháifēng hé qīzi lúnliú jià chuán.", ru: "Днём Чжай Фэн с женой по очереди управляли лодкой." },
    { sp: "", zh: "女儿在船上看书、学习、画画儿。", py: "Nǚ'ér zài chuán shang kàn shū, xuéxí, huà huàr.", ru: "Дочь на борту читала, занималась и рисовала." },
    { sp: "", zh: "下午海面平静时，翟峰会和妻子下海游泳或者钓鱼。", py: "Xiàwǔ hǎimiàn píngjìng shí, Zháifēng huì hé qīzi xià hǎi yóuyǒng huòzhě diàoyú.", ru: "Когда после полудня море успокаивалось, Чжай Фэн с женой купались или рыбачили." },
    { sp: "", zh: "该吃饭时，妻子会给全家人做一顿美味的海鲜。", py: "Gāi chīfàn shí, qīzi huì gěi quánjiā rén zuò yí dùn měiwèi de hǎixiān.", ru: "Когда наступало время еды, жена готовила для всей семьи вкусные морепродукты." },
    { sp: "", zh: "傍晚是一家人最舒适的时候。", py: "Bàngwǎn shì yìjiā rén zuì shūshì de shíhou.", ru: "Вечер был для семьи самым уютным временем." },
    { sp: "", zh: "干完活儿，一家人坐在一起，用电脑看看电影，或者聊聊天儿。", py: "Gànwán huór, yìjiā rén zuò zài yìqǐ, yòng diànnǎo kànkan diànyǐng, huòzhě liáoliao tiānr.", ru: "Закончив дела, все садились вместе, смотрели на компьютере кино или просто болтали." },
    { sp: "", zh: "这样的生活，是翟峰盼望已久的。", py: "Zhèyàng de shēnghuó, shì Zháifēng pànwàng yǐjiǔ de.", ru: "Именно о такой жизни Чжай Фэн давно мечтал." },
    { sp: "", zh: "以前陆地上的夜晚，他们在各自的房间，一家人没有更多的交流。", py: "Yǐqián lùdì shang de yèwǎn, tāmen zài gèzì de fángjiān, yìjiā rén méiyǒu gèng duō de jiāoliú.", ru: "Раньше по вечерам на суше каждый сидел в своей комнате, и вся семья почти не общалась." },
    { sp: "", zh: "中国有句老话，可上山，勿下海。", py: "Zhōngguó yǒu jù lǎohuà, kě shàng shān, wù xià hǎi.", ru: "В Китае есть старая поговорка: «В горы — можно, в море — не смей»." },
    { sp: "", zh: "美好的时刻过去后是一个紧张的夜晚。", py: "Měihǎo de shíkè guòqu hòu shì yí ge jǐnzhāng de yèwǎn.", ru: "После прекрасных мгновений наступала напряжённая ночь." },
    { sp: "", zh: "一路上，翟峰一家经历了船身着火、漏水等大大小小十多次险情。", py: "Yílù shang, Zháifēng yìjiā jīnglìle chuánshēn zháohuǒ, lòu shuǐ děng dàdà-xiǎoxiǎo shí duō cì xiǎnqíng.", ru: "За время пути семья Чжай Фэна пережила больше десятка опасных случаев — от пожара на борту до течи." },
    { sp: "", zh: "他们最怕雷电交加的时刻，因为小船随时有可能被下一道闪电击到，一家三口只能紧紧拥抱在一起，希望闪电快快过去。", py: "Tāmen zuì pà léidiàn jiāojiā de shíkè, yīnwèi xiǎo chuán suíshí yǒu kěnéng bèi xià yí dào shǎndiàn jī dào, yì jiā sān kǒu zhǐ néng jǐnjǐn yōngbào zài yìqǐ, xīwàng shǎndiàn kuàikuài guòqu.", ru: "Больше всего они боялись моментов грозы: маленькую лодку в любой миг могла поразить молния, и всем троим оставалось лишь крепко обняться, надеясь, что гроза скорее пройдёт." },
    { sp: "", zh: "在经历了八个月、航行了4000多海里之后，翟峰一家终于回到了家。", py: "Zài jīnglìle bā ge yuè, hángxíngle sìqiān duō hǎilǐ zhīhòu, Zháifēng yìjiā zhōngyú huídàole jiā.", ru: "Проведя в пути восемь месяцев и пройдя более 4000 морских миль, семья Чжай Фэна наконец вернулась домой." },
    { sp: "", zh: "翟峰相信，一切只是开始，航海就是他人生道路上一段长长的台阶，通向他想要的未来。", py: "Zháifēng xiāngxìn, yíqiè zhǐ shì kāishǐ, hánghǎi jiù shì tā rénshēng dàolù shang yí duàn chángcháng de táijiē, tōngxiàng tā xiǎng yào de wèilái.", ru: "Чжай Фэн верит: всё только начинается, а плавание — лишь длинная лестница на его жизненном пути, ведущая к желанному будущему." },
    { sp: "翟峰", zh: "我和太太想看看这个时代、这个世界到底是什么样子。", py: "Wǒ hé tàitai xiǎng kànkan zhège shídài, zhège shìjiè dàodǐ shì shénme yàngzi.", ru: "Мы с женой хотим увидеть, каковы на самом деле эта эпоха и этот мир." },
    { sp: "翟峰", zh: "人生有选择，一切可改变。", py: "Rénshēng yǒu xuǎnzé, yíqiè kě gǎibiàn.", ru: "В жизни есть выбор — и всё можно изменить." },
    { sp: "", zh: "下一站，他们想去澳洲和新西兰。", py: "Xià yí zhàn, tāmen xiǎng qù Àozhōu hé Xīnxīlán.", ru: "Следующая остановка — они хотят отправиться в Австралию и Новую Зеландию." },
    { sp: "", zh: "等待今年11月的北风，北风南下之时，他们将再次出发。", py: "Děngdài jīnnián shíyī yuè de běifēng, běifēng nán xià zhī shí, tāmen jiāng zàicì chūfā.", ru: "Дождавшись северного ветра в ноябре этого года, когда он подует к югу, они снова отправятся в путь." }
  ] }
],
"5.04": [
  { t: "子路背米 · Zilu Carrying Rice", lines: [
    { sp: "", zh: "从前，大概在距今两千五百多年前的春秋时期，有一个人叫子路，他是孔子最年长的学生。", py: "Cóngqián, dàgài zài jùjīn liǎngqiān-wǔbǎi duō nián qián de Chūnqiū shíqī, yǒu yí ge rén jiào Zǐlù, tā shì Kǒngzǐ zuì niánzhǎng de xuésheng.", ru: "Давным-давно, примерно в эпоху Чуньцю, более двух с половиной тысяч лет назад, жил человек по имени Цзы Лу — самый старший из учеников Конфуция." },
    { sp: "", zh: "流传至今的“百里背米”讲的就是他孝敬父母的故事。", py: "Liúchuán zhìjīn de \"bǎi lǐ bēi mǐ\" jiǎng de jiù shì tā xiàojìng fùmǔ de gùshi.", ru: "Дошедшая до наших дней история «пронести рис за сто ли» рассказывает как раз о том, как он проявлял почтение к родителям." },
    { sp: "", zh: "子路的父母都是农民。", py: "Zǐlù de fùmǔ dōu shì nóngmín.", ru: "Родители Цзы Лу оба были крестьянами." },
    { sp: "", zh: "由于连年的战争，家里生活非常困难。", py: "Yóuyú liánnián de zhànzhēng, jiā li shēnghuó fēicháng kùnnan.", ru: "Из-за непрекращающихся войн жизнь в семье была очень тяжёлой." },
    { sp: "", zh: "一天，子路从外面回来，听到父母在屋里说话：", py: "Yì tiān, Zǐlù cóng wàimiàn huílai, tīngdào fùmǔ zài wū li shuōhuà:", ru: "Однажды Цзы Лу вернулся домой и услышал, как родители разговаривают в доме:" },
    { sp: "父母", zh: "活了大半辈子了，别说鱼肉，只要能饱饱地吃上一顿米饭，也就满足啦！", py: "Huóle dà bàn bèizi le, bié shuō yú ròu, zhǐyào néng bǎobǎo de chīshàng yí dùn mǐfàn, yě jiù mǎnzú la!", ru: "Прожили уже больше половины жизни, о рыбе с мясом и не говорю — хоть бы раз наесться досыта простого риса, и то было бы счастьем!" },
    { sp: "", zh: "子路听了，心里觉得十分惭愧。", py: "Zǐlù tīngle, xīnli juéde shífēn cánkuì.", ru: "Услышав это, Цзы Лу почувствовал глубокий стыд." },
    { sp: "", zh: "他暗下决心：", py: "Tā àn xià juéxīn:", ru: "Он про себя твёрдо решил:" },
    { sp: "子路", zh: "一定要让父母吃上米饭，不能再委屈他们了！", py: "Yídìng yào ràng fùmǔ chīshàng mǐfàn, bù néng zài wěiqu tāmen le!", ru: "Я обязательно должен добиться того, чтобы родители ели рис, — нельзя больше заставлять их терпеть лишения!" },
    { sp: "", zh: "子路打听到百里之外有个有钱人，家里缺干活儿的人，决定去试一试。", py: "Zǐlù dǎtīngdào bǎi lǐ zhī wài yǒu ge yǒuqián rén, jiā li quē gàn huór de rén, juédìng qù shì yi shì.", ru: "Цзы Лу разузнал, что за сто ли отсюда живёт богач, которому не хватает работников, и решил попытать счастья." },
    { sp: "", zh: "那家主人见他身体结实，就留下了他。", py: "Nà jiā zhǔrén jiàn tā shēntǐ jiēshi, jiù liúxiàle tā.", ru: "Хозяин того дома увидел, что он крепкого телосложения, и взял его на работу." },
    { sp: "", zh: "子路干起活来十分勤奋，主人很喜欢这个小伙子。", py: "Zǐlù gàn qǐ huó lái shífēn qínfèn, zhǔrén hěn xǐhuan zhège xiǎohuǒzi.", ru: "Цзы Лу трудился очень усердно, и хозяин полюбил этого юношу." },
    { sp: "", zh: "半年后，当子路要回家时，发现主人给的银子比他应该得到的多了许多，子路老老实实地告诉了主人。", py: "Bàn nián hòu, dāng Zǐlù yào huí jiā shí, fāxiàn zhǔrén gěi de yínzi bǐ tā yīnggāi dédào de duōle xǔduō, Zǐlù lǎolaoshíshí de gàosule zhǔrén.", ru: "Через полгода, собираясь домой, Цзы Лу обнаружил, что хозяин дал ему серебра намного больше положенного, и честно сказал об этом хозяину." },
    { sp: "", zh: "主人笑着说：", py: "Zhǔrén xiàozhe shuō:", ru: "Хозяин с улыбкой сказал:" },
    { sp: "主人", zh: "孩子，工钱没算错，你做事勤快，这是我给你加的奖金。", py: "Háizi, gōngqián méi suàncuò, nǐ zuò shì qínkuai, zhè shì wǒ gěi nǐ jiā de jiǎngjīn.", ru: "Мальчик мой, плата подсчитана верно — просто ты работал так усердно, что это премия, которую я тебе добавил." },
    { sp: "", zh: "谢过主人，子路高兴地上路了。", py: "Xièguo zhǔrén, Zǐlù gāoxìng de shànglù le.", ru: "Поблагодарив хозяина, Цзы Лу радостно отправился в путь." },
    { sp: "", zh: "路过镇上，他买了一袋米、一块肉、两条鱼，背在后背上。", py: "Lùguò zhèn shang, tā mǎile yí dài mǐ, yí kuài ròu, liǎng tiáo yú, bēi zài hòubèi shang.", ru: "Проходя через городок, он купил мешок риса, кусок мяса и две рыбы и понёс всё это на спине." },
    { sp: "", zh: "天气非常寒冷，雪地很滑，子路不小心滑了一下，背上的米袋差点儿被甩出去。", py: "Tiānqì fēicháng hánlěng, xuědì hěn huá, Zǐlù bù xiǎoxīn huále yíxià, bèi shang de mǐdài chàdiǎnr bèi shuǎi chūqu.", ru: "Погода стояла очень холодная, снег на дороге был скользким, и Цзы Лу неосторожно поскользнулся — мешок риса на спине чуть не слетел прочь." },
    { sp: "", zh: "他顶着大雪往前走，扶着米袋的双手冻得不行，就停下来暖暖，再继续赶路。", py: "Tā dǐngzhe dà xuě wǎng qián zǒu, fúzhe mǐdài de shuāng shǒu dòng de bùxíng, jiù tíng xiàlai nuǎnnuan, zài jìxù gǎnlù.", ru: "Он шёл вперёд навстречу снегопаду, руки, придерживающие мешок, немели от холода, — тогда он останавливался погреться и снова продолжал путь." },
    { sp: "", zh: "终于到家了，见到父母，子路把给他们买的东西及剩下的工钱都交给了他们。", py: "Zhōngyú dào jiā le, jiàndào fùmǔ, Zǐlù bǎ gěi tāmen mǎi de dōngxi jí shèngxià de gōngqián dōu jiāogěile tāmen.", ru: "Наконец добравшись домой и увидев родителей, Цзы Лу отдал им всё купленное и оставшиеся деньги." },
    { sp: "", zh: "一家人高高兴兴地生火做饭，饱饱地吃了顿团圆饭。", py: "Yìjiā rén gāogāoxìngxìng de shēnghuǒ zuòfàn, bǎobǎo de chīle dùn tuányuán fàn.", ru: "Вся семья радостно развела огонь, приготовила еду и наелась досыта праздничным ужином в честь воссоединения." },
    { sp: "", zh: "后来子路的父母去世了，他也南下到了楚国。", py: "Hòulái Zǐlù de fùmǔ qùshì le, tā yě nán xià dàole Chǔguó.", ru: "Позже родители Цзы Лу скончались, и он тоже отправился на юг, в царство Чу." },
    { sp: "", zh: "楚国国君觉得他很有本领，是个人才，就留他做了官，并给他很优厚的待遇。", py: "Chǔguó guójūn juéde tā hěn yǒu běnlǐng, shì ge réncái, jiù liú tā zuòle guān, bìng gěi tā hěn yōuhòu de dàiyù.", ru: "Правитель царства Чу счёл его способным и талантливым человеком, оставил его на службе чиновником и назначил щедрое жалованье." },
    { sp: "", zh: "但他并没有因为物质条件好而感到欢喜，反而常常诚恳地说：", py: "Dàn tā bìng méiyǒu yīnwèi wùzhì tiáojiàn hǎo ér gǎndào huānxǐ, fǎn'ér chángcháng chéngkěn de shuō:", ru: "Но он вовсе не радовался хорошим материальным условиям, а, наоборот, часто искренне говорил:" },
    { sp: "子路", zh: "多么希望父母能和我一起过好日子！", py: "Duōme xīwàng fùmǔ néng hé wǒ yìqǐ guò hǎo rìzi!", ru: "Как бы я хотел, чтобы родители жили хорошей жизнью вместе со мной!" },
    { sp: "子路", zh: "我现在有了一点儿成就，可他们已经不在了，即使再想背米百里去孝敬双亲，也不可能了。", py: "Wǒ xiànzài yǒule yìdiǎnr chéngjiù, kě tāmen yǐjīng bú zài le, jíshǐ zài xiǎng bēi mǐ bǎi lǐ qù xiàojìng shuāngqīn, yě bù kěnéng le.", ru: "Теперь у меня есть кое-какие успехи, но их уже нет в живых, и даже если бы я снова захотел пронести рис за сто ли ради родителей, это уже невозможно." },
    { sp: "", zh: "中国古代有句话叫“百善孝为先”，意思是说，孝顺父母是各种美德中占第一位的。", py: "Zhōngguó gǔdài yǒu jù huà jiào \"bǎi shàn xiào wéi xiān\", yìsi shì shuō, xiàoshùn fùmǔ shì gèzhǒng měidé zhōng zhàn dì-yī wèi de.", ru: "В древнем Китае есть изречение «из ста добродетелей почтительность к родителям — первая», то есть почитание родителей стоит на первом месте среди всех добродетелей." },
    { sp: "", zh: "子路为了让父母吃到较好的食物，不怕辛苦，这种做法确实值得我们学习。", py: "Zǐlù wèile ràng fùmǔ chīdào jiào hǎo de shíwù, bú pà xīnkǔ, zhè zhǒng zuòfǎ quèshí zhídé wǒmen xuéxí.", ru: "Цзы Лу, чтобы родители могли есть более хорошую пищу, не боялся трудностей — этот поступок действительно достоин подражания." }
  ] }
],
"5.05": [
  { t: "济南的泉水 · Spring Water in Ji'nan", lines: [
    { sp: "", zh: "济南的泉水，历史悠久，最早的文字记载可以推到3000多年前。", py: "Jǐnán de quánshuǐ, lìshǐ yōujiǔ, zuìzǎo de wénzì jìzǎi kěyǐ tuīdào sānqiān duō nián qián.", ru: "Родниковые воды Цзинани имеют долгую историю: самые ранние письменные записи о них восходят к более чем 3000 годам назад." },
    { sp: "", zh: "许多文人都对它的声音、颜色、形状、味道进行过描写，留下了许多赞美泉水的诗文。", py: "Xǔduō wénrén dōu duì tā de shēngyīn, yánsè, xíngzhuàng, wèidào jìnxíngguo miáoxiě, liúxiàle xǔduō zànměi quánshuǐ de shīwén.", ru: "Многие литераторы описывали их звук, цвет, форму и вкус, оставив немало стихов и текстов, восхваляющих родниковую воду." },
    { sp: "", zh: "而济南的老百姓住在泉边，喝着这甜美的泉水，自然对它充满感激之情，从而也产生了许多关于泉水的美丽传说。", py: "Ér Jǐnán de lǎobǎixìng zhù zài quán biān, hēzhe zhè tiánměi de quánshuǐ, zìrán duì tā chōngmǎn gǎnjī zhī qíng, cóng'ér yě chǎnshēngle xǔduō guānyú quánshuǐ de měilì chuánshuō.", ru: "А простые жители Цзинани, живущие у родников и пьющие эту сладкую родниковую воду, естественно полны благодарности к ней, отчего и возникло немало прекрасных легенд о родниках." },
    { sp: "", zh: "相传很久以前，济南城里有个善良的青年，名叫鲍全，他学习医术，救了很多人。", py: "Xiāngchuán hěn jiǔ yǐqián, Jǐnán chéng li yǒu ge shànliáng de qīngnián, míng jiào Bào Quán, tā xuéxí yīshù, jiùle hěn duō rén.", ru: "По преданию, давным-давно в городе Цзинань жил добрый юноша по имени Бао Цюань; он изучал врачебное искусство и спас многих людей." },
    { sp: "", zh: "一次，他在路边救了一位晕倒的老人，并把老人接回家照顾。", py: "Yí cì, tā zài lù biān jiùle yí wèi yūndǎo de lǎorén, bìng bǎ lǎorén jiē huí jiā zhàogù.", ru: "Однажды он спас у дороги упавшего в обморок старика и забрал его к себе домой, чтобы ухаживать за ним." },
    { sp: "", zh: "这老人其实是东海龙王的哥哥。", py: "Zhè lǎorén qíshí shì Dōnghǎi Lóngwáng de gēge.", ru: "Этот старик на самом деле был старшим братом Царя-дракона Восточного моря." },
    { sp: "", zh: "通过老人的介绍，鲍全从龙王那儿求到了治病救人的白玉壶。", py: "Tōngguò lǎorén de jièshào, Bào Quán cóng Lóngwáng nàr qiúdàole zhìbìng jiùrén de báiyù hú.", ru: "Через посредство старика Бао Цюань выпросил у Царя-дракона нефритовый кувшин, исцеляющий болезни и спасающий людей." },
    { sp: "", zh: "为了不被坏人抢走，他把壶埋入地下藏了起来，于是就变成了今天有“天下第一泉”美名的趵突泉。", py: "Wèile bú bèi huàirén qiǎngzǒu, tā bǎ hú mái rù dìxià cángle qǐlai, yúshì jiù biànchéngle jīntiān yǒu \"tiānxià dì-yī quán\" měimíng de Bàotūquán.", ru: "Чтобы злые люди не отняли его, он закопал кувшин в землю и спрятал его — так и появился нынешний источник Баотуцюань, прославленный как «первый родник Поднебесной»." },
    { sp: "", zh: "如今的济南市区内，分布着大大小小七百多个天然泉，这在国内外城市中是极为少有的。", py: "Rújīn de Jǐnán shìqū nèi, fēnbùzhe dàdà-xiǎoxiǎo qībǎi duō ge tiānrán quán, zhè zài guónèiwài chéngshì zhōng shì jíwéi shǎoyǒu de.", ru: "Сегодня на территории города Цзинань разбросано более семисот природных родников разного размера — такое крайне редко встречается среди городов как в Китае, так и за рубежом." },
    { sp: "", zh: "有如此之多的泉，名字当然也少不了。", py: "Yǒu rúcǐ zhī duō de quán, míngzi dāngrán yě shǎobuliǎo.", ru: "Раз родников так много, названий для них тоже, конечно, хватает." },
    { sp: "", zh: "济南泉水的优美，还可从那独特的名字上反映出来，如：以人名命名的舜泉，以动物命名的黑虎泉，以形状命名的珍珠泉，等等。", py: "Jǐnán quánshuǐ de yōuměi, hái kě cóng nà dútè de míngzi shang fǎnyìng chūlai, rú: yǐ rénmíng mìngmíng de Shùn Quán, yǐ dòngwù mìngmíng de Hēihǔ Quán, yǐ xíngzhuàng mìngmíng de Zhēnzhū Quán, děngděng.", ru: "Изящество родников Цзинани отражается и в их своеобразных названиях, например: родник Шунь, названный в честь человека, родник Чёрного тигра, названный в честь животного, родник Жемчужина, названный по форме, и так далее." },
    { sp: "", zh: "说到这里，您也许要问，这么多、这么好的泉水是如何形成的呢？", py: "Shuōdào zhèli, nín yěxǔ yào wèn, zhème duō, zhème hǎo de quánshuǐ shì rúhé xíngchéng de ne?", ru: "Раз уж об этом зашла речь, вы, возможно, спросите: а как же образовалось столько прекрасной родниковой воды?" },
    { sp: "", zh: "济南的泉水，来自于济南市以南的广大山区，这些山区的岩石是大约四亿年前形成的一层厚厚的石灰岩。", py: "Jǐnán de quánshuǐ, láizì yú Jǐnán shì yǐ nán de guǎngdà shānqū, zhèxiē shānqū de yánshí shì dàyuē sì yì nián qián xíngchéng de yì céng hòuhòu de shíhuīyán.", ru: "Родниковая вода Цзинани берёт начало в обширных горных районах к югу от города; горные породы там представляют собой толстый слой известняка, образовавшийся около четырёхсот миллионов лет назад." },
    { sp: "", zh: "在这种石灰岩地区，陆地表面的水很容易进入地下。", py: "Zài zhè zhǒng shíhuīyán dìqū, lùdì biǎomiàn de shuǐ hěn róngyì jìnrù dìxià.", ru: "В таких известняковых районах поверхностная вода легко проникает под землю." },
    { sp: "", zh: "山区的石灰岩层，以大约三十度的角度，由南向北斜，因此大量的地下水向济南运动。", py: "Shānqū de shíhuīyán céng, yǐ dàyuē sānshí dù de jiǎodù, yóu nán xiàng běi xié, yīncǐ dàliàng de dìxiàshuǐ xiàng Jǐnán yùndòng.", ru: "Слой известняка в горах наклонён с юга на север под углом примерно тридцать градусов, поэтому огромное количество подземных вод движется в сторону Цзинани." },
    { sp: "", zh: "而济南市区的地下岩石变为了火成岩，地下水流到这里，碰到火成岩挡住了路，就积蓄起来，越积越多。", py: "Ér Jǐnán shìqū de dìxià yánshí biànwéile huǒchéngyán, dìxiàshuǐ liúdào zhèli, pèngdào huǒchéngyán dǎngzhùle lù, jiù jīxù qǐlai, yuè jī yuè duō.", ru: "А подземные породы на территории города Цзинань представляют собой изверженные породы: подземные воды, дойдя сюда и встретив на пути преграду из этих пород, начинают накапливаться, и их становится всё больше." },
    { sp: "", zh: "它无处可流，就得另找出路。", py: "Tā wú chù kě liú, jiù děi lìng zhǎo chūlù.", ru: "Ей некуда больше течь, и приходится искать другой выход." },
    { sp: "", zh: "济南旧城一带，地势低，有的地方甚至低过了地下水的水面，地下水就冲出地表，形成了众多的泉水。", py: "Jǐnán jiùchéng yídài, dìshì dī, yǒude dìfang shènzhì dīguòle dìxiàshuǐ de shuǐmiàn, dìxiàshuǐ jiù chōngchū dìbiǎo, xíngchéngle zhòngduō de quánshuǐ.", ru: "Район старого города Цзинани расположен низко, а в некоторых местах даже ниже уровня подземных вод, поэтому подземная вода прорывается на поверхность, образуя многочисленные родники." },
    { sp: "", zh: "这就是济南“泉城”美名得来的原因。", py: "Zhè jiùshì Jǐnán \"quánchéng\" měimíng dé lái de yuányīn.", ru: "Именно поэтому Цзинань получил своё прекрасное имя — «Город родников»." }
  ] }
],
"5.06": [
  { t: "除夕的由来 · Origin of Chuxi", lines: [
    { sp: "", zh: "在中国，人们把农历十二月三十日这一年中的最后一天叫作除夕，这一天，全家人会一起吃年夜饭、守岁。", py: "Zài Zhōngguó, rénmen bǎ nónglì shí'èr yuè sānshí rì zhè yì nián zhōng de zuìhòu yì tiān jiàozuò chúxī, zhè yì tiān, quánjiā rén huì yìqǐ chī niányèfàn, shǒusuì.", ru: "В Китае последний день года — тридцатое число двенадцатого месяца по лунному календарю — называют «чуси» (кануном Нового года); в этот день вся семья вместе ест новогодний ужин и «бодрствует, провожая год»." },
    { sp: "", zh: "但是，人们为什么要把年三十叫作除夕呢？", py: "Dànshì, rénmen wèishénme yào bǎ nián sānshí jiàozuò chúxī ne?", ru: "Но почему же тридцатое число года называют именно «чуси»?" },
    { sp: "", zh: "传说在很久以前，有个叫作“夕”的怪物，经常出来伤害百姓，百姓对其恨之入骨，但是又十分无奈。", py: "Chuánshuō zài hěn jiǔ yǐqián, yǒu ge jiàozuò \"Xī\" de guàiwù, jīngcháng chūlai shānghài bǎixìng, bǎixìng duì qí hènzhī-rùgǔ, dànshì yòu shífēn wúnài.", ru: "По преданию, давным-давно жило чудовище по имени «Си», которое часто выходило вредить простому народу; люди ненавидели его до глубины души, но ничего не могли поделать." },
    { sp: "", zh: "当时有个英雄叫作七郎，他英俊高大、力大无比。", py: "Dāngshí yǒu ge yīngxióng jiàozuò Qīláng, tā yīngjùn gāodà, lìdà wúbǐ.", ru: "В то время жил герой по имени Циланг — статный красавец необыкновенной силы." },
    { sp: "", zh: "七郎还有一条狗，这条狗非常勇敢，无论咬住什么都不会松口。", py: "Qīláng hái yǒu yì tiáo gǒu, zhè tiáo gǒu fēicháng yǒnggǎn, wúlùn yǎozhù shénme dōu bú huì sōng kǒu.", ru: "У Циланга была ещё собака — очень храбрая, и что бы она ни вцепилась зубами, никогда не разжимала пасть." },
    { sp: "", zh: "一天，七郎从外边回来，看到邻居家女孩的外公坐在路边哭，于是上前询问，一问才知道，原来天真可爱的女孩被“夕”吃掉了。", py: "Yì tiān, Qīláng cóng wàibian huílai, kàndào línjū jiā nǚhái de wàigōng zuò zài lùbiān kū, yúshì shàngqián xúnwèn, yí wèn cái zhīdào, yuánlái tiānzhēn kě'ài de nǚhái bèi \"Xī\" chīdiào le.", ru: "Однажды, возвращаясь домой, Циланг увидел, что дедушка соседской девочки сидит у дороги и плачет; он подошёл спросить, в чём дело, и узнал, что наивную милую девочку сожрал «Си»." },
    { sp: "", zh: "七郎暗暗下定决心一定要杀死“夕”，替百姓除掉这个制造灾害的东西。", py: "Qīláng àn'àn xiàdìng juéxīn yídìng yào shāsǐ \"Xī\", tì bǎixìng chúdiào zhège zhìzào zāihài de dōngxi.", ru: "Циланг про себя твёрдо решил во что бы то ни стало убить «Си» и избавить народ от этого источника бедствий." },
    { sp: "", zh: "于是七郎带着他的狗出发了，他到处打听“夕”的消息，但是一直找不到它。", py: "Yúshì Qīláng dàizhe tā de gǒu chūfā le, tā dàochù dǎtīng \"Xī\" de xiāoxi, dànshì yìzhí zhǎo bu dào tā.", ru: "И вот Циланг отправился в путь со своей собакой; он всюду расспрашивал о «Си», но никак не мог его найти." },
    { sp: "", zh: "这样过了差不多一年，这天正好是大年三十，七郎来到了一个热闹的城镇。", py: "Zhèyàng guòle chàbuduō yì nián, zhè tiān zhènghǎo shì dà nián sānshí, Qīláng láidàole yí ge rènao de chéngzhèn.", ru: "Так прошёл почти год; в этот день, как раз тридцатого числа последнего месяца года, Циланг пришёл в оживлённый городок." },
    { sp: "", zh: "这一年来，七郎虽然没有找到“夕”，但是了解到了很多关于“夕”的情况：它一般在太阳落山后出来伤人，到天亮前又会逃得连影子都找不着了；此外，它还特别害怕声响。", py: "Zhè yì nián lái, Qīláng suīrán méiyǒu zhǎodào \"Xī\", dànshì liǎojiědàole hěn duō guānyú \"Xī\" de qíngkuàng: tā yìbān zài tàiyáng luòshān hòu chūlai shāng rén, dào tiānliàng qián yòu huì táo de lián yǐngzi dōu zhǎo bu zháo le; cǐwài, tā hái tèbié hàipà shēngxiǎng.", ru: "За этот год Циланг хотя и не нашёл «Си», но узнал о нём много всего: обычно оно выходило вредить людям после захода солнца, а к рассвету исчезало так, что даже тени было не найти; кроме того, оно особенно боялось громких звуков." },
    { sp: "", zh: "于是七郎告诉这里的百姓，“夕”说不定晚上要出来伤害大家，让大家今晚熬夜等着，一见到“夕”就赶紧敲打东西，大家一起把“夕”杀掉。", py: "Yúshì Qīláng gàosu zhèli de bǎixìng, \"Xī\" shuōbudìng wǎnshang yào chūlai shānghài dàjiā, ràng dàjiā jīnwǎn áoyè děngzhe, yí jiàndào \"Xī\" jiù gǎnjǐn qiāodǎ dōngxi, dàjiā yìqǐ bǎ \"Xī\" shādiào.", ru: "Тогда Циланг сказал местным жителям, что «Си», возможно, выйдет вечером вредить всем, и попросил всех сегодня не спать всю ночь и ждать: как только они увидят «Си», пусть сразу же начинают стучать по чему попало, и все вместе убьют «Си»." },
    { sp: "", zh: "太阳很快落山了，到了晚上，“夕”果然出来了。", py: "Tàiyáng hěn kuài luòshān le, dàole wǎnshang, \"Xī\" guǒrán chūlai le.", ru: "Солнце вскоре зашло, и вечером «Си», как и ожидалось, появился." },
    { sp: "", zh: "它想吃一户人家的姑娘，被这家人发现了，于是他们立刻敲响了家中的锅和盆子，跟着整个镇子都响了起来。", py: "Tā xiǎng chī yí hù rénjiā de gūniang, bèi zhè jiā rén fāxiàn le, yúshì tāmen lìkè qiāoxiǎngle jiā zhōng de guō hé pénzi, gēnzhe zhěnggè zhènzi dōu xiǎngle qǐlai.", ru: "Он хотел съесть девушку из одной семьи, но эта семья заметила его, и они тут же застучали в кастрюли и тазы, а следом зазвучал и весь городок." },
    { sp: "", zh: "“夕”吓得什么似的，急忙往外逃。", py: "\"Xī\" xià de shénme shìde, jímáng wǎng wài táo.", ru: "«Си» перепугался до смерти и поспешно бросился бежать." },
    { sp: "", zh: "七郎的狗追上了“夕”，并死死地咬住了它。", py: "Qīláng de gǒu zhuīshàngle \"Xī\", bìng sǐsǐ de yǎozhùle tā.", ru: "Собака Циланга догнала «Си» и намертво вцепилась в него зубами." },
    { sp: "", zh: "七郎跑上前去，一箭射死了“夕”。", py: "Qīláng pǎo shàngqián qù, yí jiàn shèsǐle \"Xī\".", ru: "Циланг подбежал и одной стрелой убил «Си»." },
    { sp: "", zh: "除掉“夕”以后，百姓纷纷对七郎表达谢意。", py: "Chúdiào \"Xī\" yǐhòu, bǎixìng fēnfēn duì Qīláng biǎodá xièyì.", ru: "После того как «Си» был уничтожен, жители один за другим стали выражать Циланге благодарность." },
    { sp: "", zh: "由于这一天很有意义，于是人们就在每年的年三十这天晚上，仍然像那天一样整晚不睡觉，敲打出响声。", py: "Yóuyú zhè yì tiān hěn yǒu yìyì, yúshì rénmen jiù zài měinián de nián sānshí zhè tiān wǎnshang, réngrán xiàng nà tiān yíyàng zhěngwǎn bú shuìjiào, qiāodǎ chū xiǎngshēng.", ru: "Поскольку этот день оказался столь знаменательным, люди стали каждый год в ночь на тридцатое число, как и в тот раз, не спать всю ночь и стучать, производя шум." },
    { sp: "", zh: "就这样一代代传下来，形成了除夕夜守岁、放鞭炮的风俗。", py: "Jiù zhèyàng yí dài dài chuán xiàlai, xíngchéngle chúxī yè shǒusuì, fàng biānpào de fēngsú.", ru: "Так из поколения в поколение сложился обычай бодрствовать в новогоднюю ночь и запускать петарды." }
  ] }
],
"5.07": [
  { t: "盲人摸象 · The Blind Men and the Elephant", lines: [
    { sp: "", zh: "很久以前，有一个很有智慧的国王。", py: "Hěn jiǔ yǐqián, yǒu yí ge hěn yǒu zhìhuì de guówáng.", ru: "Много лет назад жил один очень мудрый правитель." },
    { sp: "", zh: "一天，他让士兵们去找一头大象和一些出生时眼睛就瞎了的人回来。", py: "Yìtiān, tā ràng shìbīngmen qù zhǎo yì tóu dàxiàng hé yìxiē chūshēng shí yǎnjing jiù xiā le de rén huílai.", ru: "Однажды он велел солдатам найти слона и несколько слепых от рождения людей и привести их." },
    { sp: "", zh: "士兵们分别去不同地方寻找，把找到的大象和盲人带到他面前。", py: "Shìbīngmen fēnbié qù bùtóng dìfang xúnzhǎo, bǎ zhǎodào de dàxiàng hé mángrén dàidào tā miànqián.", ru: "Солдаты разошлись на поиски в разные места и привели найденных слона и слепых к нему." },
    { sp: "", zh: "国王叫盲人们去摸一摸大象，问他们：", py: "Guówáng jiào mángrénmen qù mō yi mō dàxiàng, wèn tāmen:", ru: "Король велел слепым потрогать слона и спросил их:" },
    { sp: "国王", zh: "你们觉得大象是什么样的呢？", py: "Nǐmen juéde dàxiàng shì shénme yàng de ne?", ru: "«Как вы думаете, на что похож слон?»" },
    { sp: "", zh: "摸到牙齿的盲人说：", py: "Mōdào yáchǐ de mángrén shuō:", ru: "Слепой, потрогавший бивень, сказал:" },
    { sp: "盲人（牙齿）", zh: "我觉得像一个角。", py: "Wǒ juéde xiàng yí ge jiǎo.", ru: "«По-моему, он похож на рог.»" },
    { sp: "", zh: "摸到尾巴的盲人说：", py: "Mōdào wěiba de mángrén shuō:", ru: "Слепой, потрогавший хвост, сказал:" },
    { sp: "盲人（尾巴）", zh: "胡说！它像一条绳子。", py: "Húshuō! Tā xiàng yì tiáo shéngzi.", ru: "«Чепуха! Он похож на верёвку.»" },
    { sp: "", zh: "摸到大象身子的盲人说：", py: "Mōdào dàxiàng shēnzi de mángrén shuō:", ru: "Слепой, потрогавший туловище слона, сказал:" },
    { sp: "盲人（身子）", zh: "我觉得像一面又高又平的墙。", py: "Wǒ juéde xiàng yí miàn yòu gāo yòu píng de qiáng.", ru: "«По-моему, он похож на высокую ровную стену.»" },
    { sp: "", zh: "摸到大象耳朵的盲人说：", py: "Mōdào dàxiàng ěrduo de mángrén shuō:", ru: "Слепой, потрогавший ухо слона, сказал:" },
    { sp: "盲人（耳朵）", zh: "不，你们都错了，应该是像一把扇子。", py: "Bù, nǐmen dōu cuò le, yīnggāi shì xiàng yì bǎ shànzi.", ru: "«Нет, вы все ошибаетесь, он должен быть похож на веер.»" },
    { sp: "", zh: "国王笑了起来：", py: "Guówáng xiào le qǐlai:", ru: "Король рассмеялся:" },
    { sp: "国王", zh: "你们每个人都只摸到了一点，就认为自己了解全部了吗？只有片面的认识是不能下结论的。", py: "Nǐmen měi ge rén dōu zhǐ mōdàole yìdiǎn, jiù rènwéi zìjǐ liǎojiě quánbù le ma? Zhǐyǒu piànmiàn de rènshi shì bùnéng xià jiélùn de.", ru: "«Каждый из вас потрогал лишь малую часть — неужели вы думаете, что поняли всё целиком? Опираясь только на одностороннее представление, нельзя делать вывод.»" }
  ] },
  { t: "精诚所至，金石为开 · Sincerity Can Move Metal and Stone", lines: [
    { sp: "", zh: "西汉时期有一位著名的将军叫李广，他善于骑马射箭，作战勇敢，被称为“飞将军”。", py: "Xīhàn shíqī yǒu yí wèi zhùmíng de jiāngjūn jiào Lǐ Guǎng, tā shànyú qí mǎ shèjiàn, zuòzhàn yǒnggǎn, bèi chēngwéi “Fēi Jiāngjūn”.", ru: "В эпоху Западная Хань жил знаменитый полководец по имени Ли Гуан; он прекрасно ездил верхом и стрелял из лука, храбро сражался, за что его прозвали «Летающим полководцем»." },
    { sp: "", zh: "一天傍晚，他正带着士兵们在山中打猎，忽然发现远处的草丛中蹲着一只大老虎。", py: "Yì tiān bàngwǎn, tā zhèng dàizhe shìbīngmen zài shān zhōng dǎliè, hūrán fāxiàn yuǎnchù de cǎocóng zhōng dūnzhe yì zhī dà lǎohǔ.", ru: "Однажды вечером, охотясь с солдатами в горах, он вдруг заметил вдалеке в траве притаившегося большого тигра." },
    { sp: "", zh: "士兵们都紧张地围了上来，想要保护他。", py: "Shìbīngmen dōu jǐnzhāng de wéile shànglái, xiǎng yào bǎohù tā.", ru: "Солдаты, нервничая, окружили его, желая защитить." },
    { sp: "", zh: "李广摇摇头，表示不要紧。", py: "Lǐ Guǎng yáoyao tóu, biǎoshì bú yàojǐn.", ru: "Ли Гуан покачал головой, показывая, что всё в порядке." },
    { sp: "", zh: "只见他从箭袋里取出一支箭，摆好姿势，全神贯注，用尽全力向老虎射去。", py: "Zhǐ jiàn tā cóng jiàndài li qǔchū yì zhī jiàn, bǎihǎo zīshì, quánshén guànzhù, yòngjìn quánlì xiàng lǎohǔ shèqù.", ru: "Он достал из колчана стрелу, принял стойку и, полностью сосредоточившись, изо всех сил выстрелил в тигра." },
    { sp: "", zh: "过了一会儿，老虎没什么反应，士兵们小心地走上前去，想确定它是不是死了。", py: "Guòle yíhuìr, lǎohǔ méi shénme fǎnyìng, shìbīngmen xiǎoxīn de zǒu shàngqián qù, xiǎng quèdìng tā shì bu shì sǐ le.", ru: "Через некоторое время тигр никак не отреагировал, и солдаты осторожно подошли ближе, чтобы убедиться, мёртв ли он." },
    { sp: "", zh: "没想到仔细一看，被射中的竟不是老虎，而是一块形状像老虎的大石头，而且一整支箭几乎全都射到石头中去了！", py: "Méi xiǎngdào zǐxì yí kàn, bèi shèzhòng de jìng bú shì lǎohǔ, ér shì yí kuài xíngzhuàng xiàng lǎohǔ de dà shítou, érqiě yì zhěng zhī jiàn jīhū quán dōu shèdào shítou zhōng qù le!", ru: "К удивлению всех, приглядевшись, оказалось, что подстрелили вовсе не тигра, а большой камень, по форме похожий на тигра, причём вся стрела почти полностью вошла в камень!" },
    { sp: "", zh: "大家都很吃惊，连李广自己都不相信他能有这么大的力气，于是他想再试试。", py: "Dàjiā dōu hěn chījīng, lián Lǐ Guǎng zìjǐ dōu bù xiāngxìn tā néng yǒu zhème dà de lìqi, yúshì tā xiǎng zài shìshi.", ru: "Все были поражены; даже сам Ли Гуан не верил, что обладает такой силой, поэтому решил попробовать ещё раз." },
    { sp: "", zh: "可是，这次他连续换了几根箭，都没能再射进去，有的箭头碎了，有的箭杆断了，而大石头一点儿变化也没有。", py: "Kěshì, zhè cì tā liánxù huànle jǐ gēn jiàn, dōu méi néng zài shèjìnqù, yǒude jiàntóu suì le, yǒude jiàngǎn duàn le, ér dà shítou yìdiǎnr biànhuà yě méiyǒu.", ru: "Но на этот раз, сколько бы стрел подряд он ни менял, ни одна больше не входила в камень: у одних ломался наконечник, у других — древко, а сам камень нисколько не изменился." },
    { sp: "", zh: "士兵们奇怪地你看我、我看你，说：", py: "Shìbīngmen qíguài de nǐ kàn wǒ, wǒ kàn nǐ, shuō:", ru: "Солдаты в недоумении переглядывались и говорили:" },
    { sp: "士兵", zh: "哎，怎么会这样？", py: "Āi, zěnme huì zhèyàng?", ru: "«Ай, как же так получилось?»" },
    { sp: "", zh: "李广也无奈地说：", py: "Lǐ Guǎng yě wúnài de shuō:", ru: "Ли Гуан тоже беспомощно сказал:" },
    { sp: "李广", zh: "唉！大概是我不够小心了吧！", py: "Ài! Dàgài shì wǒ búgòu xiǎoxīn le ba!", ru: "«Эх! Наверное, я был недостаточно внимателен!»" },
    { sp: "", zh: "人们对这件事情感到很不解，就去问当时最有影响力的学者扬雄。", py: "Rénmen duì zhè jiàn shìqing gǎndào hěn bùjiě, jiù qù wèn dāngshí zuì yǒu yǐngxiǎnglì de xuézhě Yáng Xióng.", ru: "Люди, не в силах понять произошедшее, отправились спросить самого влиятельного учёного того времени — Ян Сюна." },
    { sp: "", zh: "扬雄回答说：", py: "Yáng Xióng huídá shuō:", ru: "Ян Сюн ответил:" },
    { sp: "扬雄", zh: "如果诚心实意，即使像金属和石头那样硬的东西也会被打动。", py: "Rúguǒ chéngxīn shíyì, jíshǐ xiàng jīnshǔ hé shítou nàyàng yìng de dōngxi yě huì bèi dǎdòng.", ru: "«Если действовать искренне и от всего сердца, то можно тронуть даже такие твёрдые вещи, как металл и камень.»" },
    { sp: "", zh: "“精诚所至，金石为开”这一成语也便由此流传下来。", py: "“Jīngchéng suǒzhì, jīnshí wéi kāi” zhè yī chéngyǔ yě biàn yóucǐ liúchuán xiàlai.", ru: "Так и пошло гулять выражение «искренность трогает даже металл и камень» (精诚所至，金石为开)." }
  ] }
],
"5.08": [
  { t: "“朝三暮四”的古今义 · \"Three in the Morning, Four in the Evening\": Old and New Meanings", lines: [
    { sp: "", zh: "成语是汉语中非常有特点的一部分词汇。", py: "Chéngyǔ shì Hànyǔ zhōng fēicháng yǒu tèdiǎn de yí bùfen cíhuì.", ru: "Идиомы — это очень своеобразная часть лексики китайского языка." },
    { sp: "", zh: "成语有固定的结构，不能随便更改；意义是整体性的，不是每个字意思的简单相加，而是综合起来表达一个完整的意思。", py: "Chéngyǔ yǒu gùdìng de jiégòu, bùnéng suíbiàn gēnggǎi; yìyì shì zhěngtǐxìng de, bú shì měi ge zì yìsi de jiǎndān xiāngjiā, ér shì zōnghé qǐlai biǎodá yí ge wánzhěng de yìsi.", ru: "У идиом фиксированная структура, которую нельзя произвольно менять; их значение целостно — это не простая сумма значений отдельных иероглифов, а объединённое выражение одного законченного смысла." },
    { sp: "", zh: "一般来说，成语的意义也是稳定的，很少发生变化，比如我们学过的“盲人摸象”和“精诚所至，金石为开”。", py: "Yìbān láishuō, chéngyǔ de yìyì yě shì wěndìng de, hěn shǎo fāshēng biànhuà, bǐrú wǒmen xuéguo de “mángrén mō xiàng” hé “jīngchéng suǒzhì, jīnshí wéi kāi”.", ru: "Как правило, значение идиом тоже устойчиво и почти не меняется — например, изученные нами «слепые ощупывают слона» и «искренность трогает даже металл и камень»." },
    { sp: "", zh: "但也有古今不同的，像我们今天要学习的“朝三暮四”。", py: "Dàn yě yǒu gǔjīn bùtóng de, xiàng wǒmen jīntiān yào xuéxí de “zhāosān mùsì”.", ru: "Но бывают и такие, что различаются в древности и сейчас, — вот как «朝三暮四» («три утром, четыре вечером»), которое мы сегодня изучим." },
    { sp: "", zh: "中国古代有一位哲学家，在他的书中讲了这样一个寓言故事：", py: "Zhōngguó gǔdài yǒu yí wèi zhéxuéjiā, zài tā de shū zhōng jiǎngle zhèyàng yí ge yùyán gùshi:", ru: "В древнем Китае жил один философ, который в своей книге рассказал такую притчу:" },
    { sp: "", zh: "从前有位老人，喂养了一群猴子当宠物。", py: "Cóngqián yǒu wèi lǎorén, wèiyǎngle yì qún hóuzi dāng chǒngwù.", ru: "Давным-давно один старик держал стаю обезьян в качестве питомцев." },
    { sp: "", zh: "相处久了，彼此居然可以从表情、声音和行为举止中了解对方的意思。", py: "Xiāngchǔ jiǔ le, bǐcǐ jūrán kěyǐ cóng biǎoqíng, shēngyīn hé xíngwéi jǔzhǐ zhōng liǎojiě duìfāng de yìsi.", ru: "Прожив вместе долгое время, они — как ни удивительно — научились понимать друг друга по выражению лица, звукам и поведению." },
    { sp: "", zh: "猴子太多，每天要吃大量的瓜果、蔬菜和粮食。", py: "Hóuzi tài duō, měitiān yào chī dàliàng de guāguǒ, shūcài hé liángshi.", ru: "Обезьян было слишком много, и каждый день они съедали огромное количество фруктов, овощей и зерна." },
    { sp: "", zh: "然而，一个普通的家庭，财产不多，哪有那么大的财力满足一群猴子对食物的长期需要呢？", py: "Rán'ér, yí ge pǔtōng de jiātíng, cáichǎn bù duō, nǎ yǒu nàme dà de cáilì mǎnzú yì qún hóuzi duì shíwù de chángqī xūyào ne?", ru: "Однако у обычной семьи небогатое имущество — откуда взять столько средств, чтобы долго удовлетворять потребности целой стаи обезьян в еде?" },
    { sp: "", zh: "老人甚至必须减少家人的消费，好节省些食物拿去喂养猴子。", py: "Lǎorén shènzhì bìxū jiǎnshǎo jiārén de xiāofèi, hǎo jiéshěng xiē shíwù ná qù wèiyǎng hóuzi.", ru: "Старику даже пришлось сократить расходы своей семьи, чтобы сэкономить немного еды для обезьян." },
    { sp: "", zh: "他注意到该限制猴子的食量了。", py: "Tā zhùyìdào gāi xiànzhì hóuzi de shíliàng le.", ru: "Он понял, что пора ограничить количество еды для обезьян." },
    { sp: "", zh: "问题是，猴子不像猪、狗，吃不饱时仅仅只是叫叫，它们如果得不到好的待遇，就会像一群调皮的孩子，经常跟人淘气。", py: "Wèntí shì, hóuzi bú xiàng zhū, gǒu, chī bu bǎo shí jǐnjǐn zhǐshì jiàojiao, tāmen rúguǒ dé bu dào hǎo de dàiyù, jiù huì xiàng yì qún tiáopí de háizi, jīngcháng gēn rén táoqì.", ru: "Проблема в том, что обезьяны — не как свиньи или собаки, которые просто немного покричат, если недоедят: если с ними плохо обращаться, они, словно ватага озорных детей, то и дело будут проказничать с людьми." },
    { sp: "", zh: "老人的朋友送给他很多橡子，这是一种猴子爱吃的果实。", py: "Lǎorén de péngyou sònggěi tā hěn duō xiàngzi, zhè shì yì zhǒng hóuzi ài chī de guǒshí.", ru: "Друг старика подарил ему много жёлудей — плодов, которые обезьяны очень любят есть." },
    { sp: "", zh: "在其他粮食不足的情况下，用橡子喂猴子倒是个办法。", py: "Zài qítā liángshi bùzú de qíngkuàng xià, yòng xiàngzi wèi hóuzi dàoshi ge bànfǎ.", ru: "В условиях нехватки прочего корма кормить обезьян желудями оказалось неплохим выходом." },
    { sp: "", zh: "于是老人对猴子们说：", py: "Yúshì lǎorén duì hóuzimen shuō:", ru: "И тогда старик сказал обезьянам:" },
    { sp: "老人", zh: "今后你们除了吃馒头，还可以再吃一些橡子。我早上给你们三颗，晚上给四颗。", py: "Jīnhòu nǐmen chúle chī mántou, hái kěyǐ zài chī yìxiē xiàngzi. Wǒ zǎoshang gěi nǐmen sān kē, wǎnshang gěi sì kē.", ru: "«Отныне вы, помимо пампушек-маньтоу, сможете есть ещё и жёлуди. Утром я буду давать вам три штуки, а вечером — четыре.»" },
    { sp: "", zh: "猴子们似乎只弄懂了主人前面说的一个“三”，觉得自己吃了亏，一个个立起身子跳来跳去，对着老人大喊大叫地发脾气。", py: "Hóuzimen sìhū zhǐ nòngdǒngle zhǔrén qiánmiàn shuō de yí ge “sān”, juéde zìjǐ chīle kuī, yí gègè lìqǐ shēnzi tiàolái tiàoqù, duìzhe lǎorén dàhǎn dàjiào de fā píqi.", ru: "Обезьяны, похоже, поняли из слов хозяина только цифру «три» и решили, что их обделили: они одна за другой вставали и прыгали туда-сюда, крича и злясь на старика." },
    { sp: "", zh: "老人见猴子们不接受，就换了一种方式，安慰它们说：", py: "Lǎorén jiàn hóuzimen bù jiēshòu, jiù huànle yì zhǒng fāngshì, ānwèi tāmen shuō:", ru: "Видя, что обезьяны не согласны, старик сменил тактику и, успокаивая их, сказал:" },
    { sp: "老人", zh: "要不这样吧，既然你们觉得少，那就改成每天早上四颗，晚上三颗，这样总够了吧？", py: "Yàobù zhèyàng ba, jìrán nǐmen juéde shǎo, nà jiù gǎichéng měitiān zǎoshang sì kē, wǎnshang sān kē, zhèyàng zǒng gòu le ba?", ru: "«А давайте вот как: раз уж вам кажется, что мало, изменим на четыре штуки по утрам и три вечером — так уж точно хватит?»" },
    { sp: "", zh: "猴子把主人前面说的一个“四”当成全天多得了的橡子，所以马上安静下来，显得格外开心。", py: "Hóuzi bǎ zhǔrén qiánmiàn shuō de yí ge “sì” dàngchéng quántiān duō déle de xiàngzi, suǒyǐ mǎshàng ānjìng xiàlai, xiǎnde géwài kāixīn.", ru: "Обезьяны восприняли произнесённую хозяином цифру «четыре» как то, что за весь день они получат больше желудей, поэтому сразу успокоились и стали выглядеть чрезвычайно довольными." },
    { sp: "", zh: "老人看着这情景，哈哈地笑了。", py: "Lǎorén kànzhe zhè qíngjǐng, hāhā de xiào le.", ru: "Старик, глядя на эту картину, рассмеялся: ха-ха." },
    { sp: "", zh: "哲学家用这个故事告诉人们，不要太关心生死、得失，因为到最后我们会发现没有失去什么，也没有得到什么。", py: "Zhéxuéjiā yòng zhège gùshi gàosu rénmen, búyào tài guānxīn shēngsǐ, déshī, yīnwèi dào zuìhòu wǒmen huì fāxiàn méiyǒu shīqù shénme, yě méiyǒu dédào shénme.", ru: "Этим рассказом философ хотел сказать людям: не стоит слишком беспокоиться о жизни и смерти, приобретениях и потерях, ведь в конце концов окажется, что мы ничего не потеряли и ничего не приобрели." },
    { sp: "", zh: "不过，发展到今天，“朝三暮四”这个成语的意义已经完全改变了。你知道它现在是什么意思吗？", py: "Búguò, fāzhǎn dào jīntiān, “zhāosān mùsì” zhège chéngyǔ de yìyì yǐjīng wánquán gǎibiàn le. Nǐ zhīdào tā xiànzài shì shénme yìsi ma?", ru: "Однако к сегодняшнему дню значение идиомы «朝三暮四» полностью изменилось. Знаете ли вы, что она означает сейчас?" }
  ] }
],
"5.09": [
  { t: "别样鲁迅 · The Lu Xun You Don't Know", lines: [
    { sp: "", zh: "美食很大一部分是靠名人推动的，这一点在民国时期表现得尤其突出。", py: "Měishí hěn dà yí bùfen shì kào míngrén tuīdòng de, zhè yìdiǎn zài Mínguó shíqī biǎoxiàn de yóuqí tūchū.", ru: "Значительная часть популярности гастрономии продвигается знаменитостями, и особенно ярко это проявилось в эпоху Китайской Республики." },
    { sp: "", zh: "例如著名的文学家鲁迅，在吃喝这件事上，就算是个地道的行家，不但会吃，还会亲自动手做，对许多美食都有独特的见解。", py: "Bǐrú zhùmíng de wénxuéjiā Lǔ Xùn, zài chīhē zhè jiàn shì shang, jiù suàn shì ge dìdao de hángjia, búdàn huì chī, hái huì qīnzì dòngshǒu zuò, duì xǔduō měishí dōu yǒu dútè de jiànjiě.", ru: "Например, знаменитый писатель Лу Синь в вопросах еды и питья считался настоящим знатоком: он не только умел вкусно поесть, но и сам готовил, а о многих блюдах имел собственное, оригинальное мнение." },
    { sp: "", zh: "这是近代新时尚。", py: "Zhè shì jìndài xīn shíshàng.", ru: "Это была новая мода Нового времени." },
    { sp: "", zh: "北京是鲁迅长期生活过的城市，仅从这一时期鲁迅写作的日记中，我们发现他去过的知名餐馆就有65家，另外，他还很爱吃稻香村的点心。", py: "Běijīng shì Lǔ Xùn chángqī shēnghuóguo de chéngshì, jǐn cóng zhè yì shíqī Lǔ Xùn xiězuò de rìjì zhōng, wǒmen fāxiàn tā qùguo de zhīmíng cānguǎn jiù yǒu liùshíwǔ jiā, lìngwài, tā hái hěn ài chī Dàoxiāngcūn de diǎnxin.", ru: "Пекин — город, где Лу Синь долго жил; только по дневникам, которые он вёл в этот период, мы обнаруживаем, что он побывал в 65 известных ресторанах, а кроме того, очень любил десерты из кондитерской «Даосянцунь»." },
    { sp: "", zh: "作为大作家、大学问家，鲁迅对吃很讲究，吃的内容在他的日记里占了很大一部分。", py: "Zuòwéi dà zuòjiā, dà xuéwenjiā, Lǔ Xùn duì chī hěn jiǎngjiu, chī de nèiróng zài tā de rìjì li zhànle hěn dà yí bùfen.", ru: "Будучи великим писателем и большим учёным, Лу Синь был очень взыскателен в еде, и записи о еде занимали значительную часть его дневника." },
    { sp: "", zh: "在众多餐馆里，鲁迅去得最多、最喜欢的是广和居，平均每周都要去一次。", py: "Zài zhòngduō cānguǎn li, Lǔ Xùn qù de zuì duō, zuì xǐhuan de shì Guǎnghéjū, píngjūn měi zhōu dōu yào qù yí cì.", ru: "Среди множества ресторанов Лу Синь чаще всего посещал и больше всего любил «Гуанхэцзюй» — в среднем бывал там раз в неделю." },
    { sp: "", zh: "鲁迅经常到这家店的一个重要原因是距离近，广和居的大门就在他当时住的胡同的斜对面。", py: "Lǔ Xùn jīngcháng dào zhè jiā diàn de yí ge zhòngyào yuányīn shì jùlí jìn, Guǎnghéjū de dàmén jiù zài tā dāngshí zhù de hútòng de xié duìmiàn.", ru: "Одна из важных причин, почему Лу Синь часто ходил в это заведение, — близость: главный вход «Гуанхэцзюй» находился наискосок от переулка, где он тогда жил." },
    { sp: "", zh: "位于菜市口附近的广和居是北京“八大居”之首，在民国时期非常出名。", py: "Wèiyú Càishìkǒu fùjìn de Guǎnghéjū shì Běijīng “bā dà jū” zhī shǒu, zài Mínguó shíqī fēicháng chūmíng.", ru: "Расположенный неподалёку от Цайшикоу, «Гуанхэцзюй» возглавлял список «восьми больших заведений» Пекина и был очень знаменит в эпоху Китайской Республики." },
    { sp: "", zh: "广和居算不上豪华，但却很适合朋友在这里聚会、热闹。", py: "Guǎnghéjū suàn bu shàng háohuá, dàn què hěn shìhé péngyou zài zhèlǐ jùhuì, rènao.", ru: "«Гуанхэцзюй» нельзя было назвать роскошным, зато он прекрасно подходил для дружеских встреч и шумных застолий." },
    { sp: "", zh: "这里特别欢迎文人的光临，为他们的聚会创造了很好的条件。", py: "Zhèlǐ tèbié huānyíng wénrén de guānglín, wèi tāmen de jùhuì chuàngzàole hěn hǎo de tiáojiàn.", ru: "Здесь особенно радушно принимали людей пера, создавая прекрасные условия для их встреч." },
    { sp: "", zh: "广和居院里分成大小不同的各种房间，有一个人的，有三五人小聚的，也有十多个人大聚会的。", py: "Guǎnghéjū yuàn li fēnchéng dàxiǎo bùtóng de gèzhǒng fángjiān, yǒu yí ge rén de, yǒu sān wǔ rén xiǎojù de, yě yǒu shí duō ge rén dà jùhuì de.", ru: "Двор «Гуанхэцзюй» был разделён на комнаты разного размера: были и для одного человека, и для небольшой компании из трёх-пяти, и для больших застолий на десяток с лишним человек." },
    { sp: "", zh: "这大大满足了鲁迅爱和朋友吃饭的要求。", py: "Zhè dàdà mǎnzúle Lǔ Xùn ài hé péngyou chīfàn de yāoqiú.", ru: "Это прекрасно удовлетворяло любовь Лу Синя к застольям с друзьями." },
    { sp: "", zh: "他爱好交际，大方好客，常呼朋唤友，多数是三五个人一起吃，有时甚至会直接让广和居送外卖到家里，在家招待朋友。", py: "Tā àihào jiāojì, dàfang hàokè, cháng hūpéng huànyǒu, duōshù shì sān wǔ ge rén yìqǐ chī, yǒushí shènzhì huì zhíjiē ràng Guǎnghéjū sòng wàimài dào jiā li, zài jiā zhāodài péngyou.", ru: "Он любил общение, был щедрым и гостеприимным, часто собирал друзей; чаще всего ели компанией в три-пять человек, а порой он даже заказывал доставку еды из «Гуанхэцзюй» прямо домой, принимая друзей у себя." },
    { sp: "", zh: "当然最重要的还是因为广和居有鲁迅喜欢的菜。", py: "Dāngrán zuì zhòngyào de háishi yīnwèi Guǎnghéjū yǒu Lǔ Xùn xǐhuan de cài.", ru: "Конечно, самое важное всё же в том, что в «Гуанхэцзюй» подавали блюда, которые любил Лу Синь." },
    { sp: "", zh: "那里的菜既有高档的，也有适合普通百姓的，样样都让人有胃口。", py: "Nàlǐ de cài jì yǒu gāodàng de, yě yǒu shìhé pǔtōng bǎixìng de, yàngyàng dōu ràng rén yǒu wèikǒu.", ru: "Тамошние блюда были и высококлассными, и доступными для простых людей — всё вызывало аппетит." },
    { sp: "", zh: "鲁迅也爱喝酒，虽然明明知道自己有胃病，不应该喝酒，但却很难戒掉。", py: "Lǔ Xùn yě ài hē jiǔ, suīrán míngmíng zhīdào zìjǐ yǒu wèibìng, bù yīnggāi hē jiǔ, dàn què hěn nán jièdiào.", ru: "Лу Синь также любил выпить: хотя он прекрасно знал, что у него болезнь желудка и пить ему нельзя, бросить это было очень трудно." },
    { sp: "", zh: "他是每顿饭必喝酒的人。", py: "Tā shì měi dùn fàn bì hē jiǔ de rén.", ru: "Он был человеком, который непременно пил за каждой трапезой." },
    { sp: "", zh: "现在保存的历史资料记载，他和郁达夫一起喝酒的次数最多。", py: "Xiànzài bǎocún de lìshǐ zīliào jìzǎi, tā hé Yù Dáfū yìqǐ hē jiǔ de cìshù zuì duō.", ru: "Согласно сохранившимся историческим сведениям, чаще всего он выпивал вместе с Юй Дафу." },
    { sp: "", zh: "鲁迅酒量不大，经常喝醉，而且在喝酒的过程中烟不离手。", py: "Lǔ Xùn jiǔliàng bú dà, jīngcháng hēzuì, érqiě zài hē jiǔ de guòchéng zhōng yān bù lí shǒu.", ru: "Лу Синь пил немного, часто напивался, и во время выпивки сигарета не покидала его рук." },
    { sp: "", zh: "郁达夫在1933年曾经作诗形容他：", py: "Yù Dáfū zài yījiǔsānsān nián céngjīng zuò shī xíngróng tā:", ru: "В 1933 году Юй Дафу однажды написал о нём стихи:" },
    { sp: "郁达夫", zh: "醉眼蒙眬上酒楼，彷徨呐喊两悠悠", py: "Zuì yǎn ménglóng shàng jiǔlóu, pánghuáng nàhǎn liǎng yōuyōu", ru: "«С хмельным, затуманенным взором поднимается в винный дом — „Блуждания“ и „Крик“ (его книги) звучат неспешно, отстранённо»" },
    { sp: "", zh: "描写得十分形象。", py: "Miáoxiě de shífēn xíngxiàng.", ru: "Описано это было очень живо и образно." }
  ] }
],
"5.10": [
  { t: "争论的奇迹 · Miracle of Debate", lines: [
    { sp: "", zh: "1872年的一天，在美国加利福尼亚州的一个酒店里，斯坦福与科恩围绕“马奔跑时蹄子是否着地”进行了辩论。", py: "Yībāqī'èr nián de yì tiān, zài Měiguó Jiālìfúníyà Zhōu de yí ge jiǔdiàn li, Sītǎnfú yǔ Kē'ēn wéirào “mǎ bēnpǎo shí tízi shìfǒu zháodì” jìnxíngle biànlùn.", ru: "Однажды в 1872 году в одном отеле американского штата Калифорния Стэнфорд и Коэн вели спор о том, «касается ли копыто земли, когда лошадь скачет»." },
    { sp: "", zh: "斯坦福认为，马奔跑得那么快，在跳起时四蹄应该都是不落地的；而科恩认为，马要是四蹄都不着地，那不是成了青蛙啦？", py: "Sītǎnfú rènwéi, mǎ bēnpǎo de nàme kuài, zài tiàoqǐ shí sì tí yīnggāi dōu shì bú luòdì de; ér Kē'ēn rènwéi, mǎ yàoshi sì tí dōu bù zháodì, nà bú shì chéngle qīngwā la?", ru: "Стэнфорд считал, что лошадь скачет так быстро, что в момент прыжка все четыре копыта не должны касаться земли; а Коэн полагал: если бы у лошади все четыре копыта не касались земли, разве она не превратилась бы тогда в лягушку?" },
    { sp: "", zh: "应该是始终有一蹄着地。", py: "Yīnggāi shì shǐzhōng yǒu yì tí zháodì.", ru: "(По его мнению) всегда должно оставаться хотя бы одно копыто на земле." },
    { sp: "", zh: "两人各执一词，争论得脸红脖子粗，谁也说服不了谁。", py: "Liǎng rén gè zhí yì cí, zhēnglùn de liǎnhóng bózi cū, shéi yě shuōfú bùliǎo shéi.", ru: "Оба стояли на своём, спорили так, что краснели и надували шеи, и никто не мог переубедить другого." },
    { sp: "", zh: "于是他们就请英国摄影师麦布里奇来判断，可麦布里奇也弄不清楚。", py: "Yúshì tāmen jiù qǐng Yīngguó shèyǐngshī Màibùlǐqí lái pànduàn, kě Màibùlǐqí yě nòng bu qīngchu.", ru: "Тогда они пригласили английского фотографа Мейбриджа рассудить их, но и Мейбридж не смог разобраться." },
    { sp: "", zh: "不过摄影师毕竟是摄影师，主意还是有的。", py: "Búguò shèyǐngshī bìjìng shì shèyǐngshī, zhǔyi háishi yǒu de.", ru: "Однако фотограф есть фотограф — идея у него всё же нашлась." },
    { sp: "", zh: "他们一起来到一个操场，在一条跑道的一边等距离放上24个照相机，照相机对准跑道；在跑道另一边打24个洞，分别插进24根木棍，木棍上系着细线，细线穿过跑道，接上相机快门。", py: "Tāmen yìqǐ láidào yí ge cāochǎng, zài yì tiáo pǎodào de yìbiān děng jùlí fàngshang èrshísì ge zhàoxiàngjī, zhàoxiàngjī duìzhǔn pǎodào; zài pǎodào lìng yìbiān dǎ èrshísì ge dòng, fēnbié chājìn èrshísì gēn mùgùn, mùgùn shang jìzhe xìxiàn, xìxiàn chuānguò pǎodào, jiēshang xiàngjī kuàimén.", ru: "Они вместе пришли на спортивную площадку и расставили с равными промежутками 24 фотоаппарата вдоль одной стороны беговой дорожки, направив их на дорожку; на другой стороне дорожки пробили 24 отверстия и вставили в них 24 деревянных колышка, к которым привязали тонкие нити; нити протянули через дорожку и подсоединили к затворам фотоаппаратов." },
    { sp: "", zh: "一切都准备好了，麦布里奇让一匹马从跑道的一头飞奔到另一头，马一边跑，一边按顺序撞断拦路的24根细线，相机连续拍下了24张相片，相邻两张相片的差距都很小。", py: "Yíqiè dōu zhǔnbèi hǎo le, Màibùlǐqí ràng yì pǐ mǎ cóng pǎodào de yì tóu fēibēn dào lìng yì tóu, mǎ yìbiān pǎo, yìbiān àn shùnxù zhuàngduàn lánlù de èrshísì gēn xìxiàn, xiàngjī liánxù pāixiàle èrshísì zhāng xiàngpiàn, xiānglín liǎng zhāng xiàngpiàn de chājù dōu hěn xiǎo.", ru: "Когда всё было готово, Мейбридж пустил лошадь галопом от одного конца дорожки к другому; лошадь бежала и по порядку обрывала преграждавшие путь 24 нити, а фотоаппараты подряд сделали 24 снимка, причём разница между соседними снимками была очень мала." },
    { sp: "", zh: "相片显示：马奔跑时始终有一蹄着地，科恩赢了。", py: "Xiàngpiàn xiǎnshì: mǎ bēnpǎo shí shǐzhōng yǒu yì tí zháodì, Kē'ēn yíng le.", ru: "Снимки показали: во время бега у лошади всегда есть одно копыто на земле — Коэн выиграл." },
    { sp: "", zh: "事后，有人无意识地快速拉动那一长串相片，“奇迹”出现了：各张相片中静止的马连成了一匹运动的马，相片“活”了。", py: "Shìhòu, yǒurén wúyìshí de kuàisù lādòng nà yì cháng chuàn xiàngpiàn, “qíjì” chūxiàn le: gè zhāng xiàngpiàn zhōng jìngzhǐ de mǎ liánchéngle yì pǐ yùndòng de mǎ, xiàngpiàn “huó” le.", ru: "После этого кто-то неосознанно быстро протянул эту длинную ленту снимков, и произошло «чудо»: неподвижные лошади на отдельных снимках слились в одну движущуюся лошадь — фотографии «ожили»." },
    { sp: "", zh: "这就是电影最早的样子。", py: "Zhè jiùshì diànyǐng zuìzǎo de yàngzi.", ru: "Так выглядело кино в самом своём начале." },
    { sp: "", zh: "经过艰苦的试验，电影拍摄技术逐渐改进、成熟。", py: "Jīngguò jiānkǔ de shìyàn, diànyǐng pāishè jìshù zhújiàn gǎijìn, chéngshú.", ru: "Пройдя через тяжёлые испытания, техника киносъёмки постепенно улучшалась и достигла зрелости." },
    { sp: "", zh: "1895年12月28日，法国人卢米埃尔兄弟在巴黎第一次向公众播放了短片《火车到站》，这一天后来成为电影产生的纪念日，兄弟俩也成为历史上最早的电影导演。", py: "Yībājiǔwǔ nián shí'èr yuè èrshíbā rì, Fǎguórén Lúmǐ'āi'ěr xiōngdì zài Bālí dìyī cì xiàng gōngzhòng bōfàngle duǎnpiàn “Huǒchē Dàozhàn”, zhè yì tiān hòulái chéngwéi diànyǐng chǎnshēng de jìniànrì, xiōngdì liǎ yě chéngwéi lìshǐ shang zuìzǎo de diànyǐng dǎoyǎn.", ru: "28 декабря 1895 года французские братья Люмьер впервые публично показали в Париже короткий фильм «Прибытие поезда»; этот день впоследствии стал памятной датой рождения кино, а сами братья вошли в историю как первые кинорежиссёры." },
    { sp: "", zh: "留心生活的每一瞬间，并为之争论，适时请求帮助、认真研究，或许重大发现就在你的眼前。", py: "Liúxīn shēnghuó de měi yí shùnjiān, bìng wéi zhī zhēnglùn, shìshí qǐngqiú bāngzhù, rènzhēn yánjiū, huòxǔ zhòngdà fāxiàn jiù zài nǐ de yǎnqián.", ru: "Обращайте внимание на каждое мгновение жизни, спорьте о нём, вовремя просите о помощи и добросовестно исследуйте — и, возможно, важное открытие окажется прямо перед вашими глазами." }
  ] }
],
"5.11": [
  { t: "闹钟的危害 · Harm of Alarm Clocks", lines: [
    { sp: "", zh: "医学研究证明，人类睡眠有其特定的机制，自然醒是最符合人体生物钟规律的。", py: "Yīxué yánjiū zhèngmíng, rénlèi shuìmián yǒu qí tèdìng de jīzhì, zìrán xǐng shì zuì fúhé réntǐ shēngwùzhōng guīlǜ de.", ru: "Медицинские исследования доказывают, что у человеческого сна есть свой особый механизм, и естественное пробуждение лучше всего соответствует закономерностям биологических часов организма." },
    { sp: "", zh: "光线是自然醒的必要条件，是人体内的生物闹钟。", py: "Guāngxiàn shì zìrán xǐng de bìyào tiáojiàn, shì réntǐ nèi de shēngwù nàozhōng.", ru: "Свет — необходимое условие для естественного пробуждения, это своего рода биологический будильник внутри организма." },
    { sp: "", zh: "早晨，人体感受到逐渐变强的太阳光线，新陈代谢随之加快，人逐渐从熟睡过渡到浅睡，直到醒来。", py: "Zǎochén, réntǐ gǎnshòudào zhújiàn biànqiáng de tàiyáng guāngxiàn, xīnchén dàixiè suí zhī jiākuài, rén zhújiàn cóng shúshuì guòdù dào qiǎnshuì, zhídào xǐnglái.", ru: "Утром организм ощущает постепенно усиливающийся солнечный свет, обмен веществ соответственно ускоряется, и человек постепенно переходит от глубокого сна к поверхностному, пока не проснётся." },
    { sp: "", zh: "这就是阴雨天人们往往喜欢睡懒觉的原因。", py: "Zhè jiùshì yīnyǔtiān rénmen wǎngwǎng xǐhuan shuì lǎnjiào de yuányīn.", ru: "Именно поэтому в пасмурные, дождливые дни люди часто любят поспать подольше." },
    { sp: "", zh: "紧张的现代生活，使很多上班的人无法享受轻松舒适的睡眠、自然地醒来，闹钟的用途就显得格外重要了。", py: "Jǐnzhāng de xiàndài shēnghuó, shǐ hěn duō shàngbān de rén wúfǎ xiǎngshòu qīngsōng shūshì de shuìmián, zìrán de xǐnglái, nàozhōng de yòngtú jiù xiǎnde géwài zhòngyào le.", ru: "Напряжённая современная жизнь лишает многих работающих людей возможности наслаждаться спокойным, комфортным сном и просыпаться естественным образом, поэтому роль будильника становится особенно важной." },
    { sp: "", zh: "但实验研究证明，人们对自然醒与被闹钟铃声叫醒这两种方式所产生的反应是很不相同的。", py: "Dàn shíyàn yánjiū zhèngmíng, rénmen duì zìrán xǐng yǔ bèi nàozhōng língshēng jiàoxǐng zhè liǎng zhǒng fāngshì suǒ chǎnshēng de fǎnyìng shì hěn bù xiāngtóng de.", ru: "Однако экспериментальные исследования доказывают, что реакции людей на естественное пробуждение и на пробуждение от звонка будильника весьма различны." },
    { sp: "", zh: "从睡眠状态过渡到清醒状态时，人的呼吸会从16次/分钟提高到24次/分钟，心跳每分钟加快10次。", py: "Cóng shuìmián zhuàngtài guòdù dào qīngxǐng zhuàngtài shí, rén de hūxī huì cóng shíliù cì/fēnzhōng tígāo dào èrshísì cì/fēnzhōng, xīntiào měi fēnzhōng jiākuài shí cì.", ru: "При переходе от состояния сна к состоянию бодрствования частота дыхания у человека повышается с 16 до 24 раз в минуту, а сердцебиение учащается на 10 ударов в минуту." },
    { sp: "", zh: "如果突然被闹钟叫醒，将在心理上使人产生心慌、情绪低落、感觉没睡醒等不适。", py: "Rúguǒ tūrán bèi nàozhōng jiàoxǐng, jiāng zài xīnlǐ shang shǐ rén chǎnshēng xīnhuāng, qíngxù dīluò, gǎnjué méi shuìxǐng děng búshì.", ru: "Если человека резко разбудит будильник, это психологически вызовет у него тревогу, подавленное настроение, ощущение недосыпа и другие неприятные симптомы." },
    { sp: "", zh: "如果是从深度睡眠中被突然叫醒，那么，人的短期记忆能力、计算技能都会受到影响，这些能力最多为正常状态的65%，与醉酒者相当。", py: "Rúguǒ shì cóng shēndù shuìmián zhōng bèi tūrán jiàoxǐng, nàme, rén de duǎnqī jìyì nénglì, jìsuàn jìnéng dōu huì shòudào yǐngxiǎng, zhèxiē nénglì zuìduō wéi zhèngcháng zhuàngtài de bǎifēnzhī liùshíwǔ, yǔ zuìjiǔzhě xiāngdāng.", ru: "Если человека резко разбудят из глубокого сна, это повлияет на его кратковременную память и вычислительные способности — они составят максимум 65% от нормального уровня, что сравнимо с состоянием опьянения." },
    { sp: "", zh: "出于自我保护，被闹钟叫醒时我们的身体会提高体内的肾上腺素水平。", py: "Chūyú zìwǒ bǎohù, bèi nàozhōng jiàoxǐng shí wǒmen de shēntǐ huì tígāo tǐnèi de shènshàngxiànsù shuǐpíng.", ru: "В целях самозащиты, когда нас будит будильник, организм повышает уровень адреналина." },
    { sp: "", zh: "这种状态如果持续数天、数周、数月，将导致高血压、失眠和一些精神问题等。", py: "Zhè zhǒng zhuàngtài rúguǒ chíxù shù tiān, shù zhōu, shù yuè, jiāng dǎozhì gāoxuèyā, shīmián hé yìxiē jīngshén wèntí děng.", ru: "Если такое состояние сохраняется несколько дней, недель или месяцев, это приведёт к повышенному давлению, бессоннице и некоторым психическим проблемам." },
    { sp: "", zh: "研究发现，突然被闹铃惊醒的人比自然醒的人血压更高、心跳更快。", py: "Yánjiū fāxiàn, tūrán bèi nàolíng jīngxǐng de rén bǐ zìrán xǐng de rén xuèyā gèng gāo, xīntiào gèng kuài.", ru: "Исследования показали, что у людей, резко разбуженных звонком будильника, давление выше, а сердцебиение чаще, чем у тех, кто просыпается естественно." },
    { sp: "", zh: "对此，专家解释说，人在睡眠时，身体会发生一些变化，因此人们在早上醒来时更容易发病，而闹铃则会使发病的可能性变得更大。", py: "Duì cǐ, zhuānjiā jiěshì shuō, rén zài shuìmián shí, shēntǐ huì fāshēng yìxiē biànhuà, yīncǐ rénmen zài zǎoshang xǐnglái shí gèng róngyì fābìng, ér nàolíng zé huì shǐ fābìng de kěnéngxìng biàn de gèng dà.", ru: "По этому поводу специалисты объясняют: во время сна в организме происходят некоторые изменения, поэтому утром при пробуждении люди более подвержены заболеваниям, а звонок будильника ещё больше увеличивает эту вероятность." },
    { sp: "", zh: "如果你必须定个闹钟，应采用柔和的声音或音乐。", py: "Rúguǒ nǐ bìxū dìng ge nàozhōng, yīng cǎiyòng róuhé de shēngyīn huò yīnyuè.", ru: "Если вам обязательно нужно завести будильник, следует использовать мягкий звук или музыку." },
    { sp: "", zh: "各种醒来方式中，当然是自然醒最符合我们的愿望。", py: "Gèzhǒng xǐnglái fāngshì zhōng, dāngrán shì zìrán xǐng zuì fúhé wǒmen de yuànwàng.", ru: "Среди всех способов пробуждения, конечно, естественное пробуждение больше всего соответствует нашим желаниям." },
    { sp: "", zh: "可谁能替你拉开窗帘让阳光照进来呢？", py: "Kě shéi néng tì nǐ lākāi chuānglián ràng yángguāng zhào jìnlai ne?", ru: "Но кто же за вас отдёрнет шторы, чтобы впустить солнечный свет?" },
    { sp: "", zh: "近年来，市场上出现了一种新的电子产品，名为“光闹钟”。", py: "Jìnnián lái, shìchǎng shang chūxiànle yì zhǒng xīn de diànzǐ chǎnpǐn, míngwéi “guāng nàozhōng”.", ru: "В последние годы на рынке появился новый электронный продукт под названием «световой будильник»." },
    { sp: "", zh: "它能在室内模仿早晨自然光线的变化，通过光线的作用使人在设定的时间里自然地醒来，可避免传统闹钟突然惊醒对人体健康的伤害。", py: "Tā néng zài shìnèi mófǎng zǎochén zìrán guāngxiàn de biànhuà, tōngguò guāngxiàn de zuòyòng shǐ rén zài shèdìng de shíjiān li zìrán de xǐnglái, kě bìmiǎn chuántǒng nàozhōng tūrán jīngxǐng duì réntǐ jiànkāng de shānghài.", ru: "Он способен имитировать в помещении изменение естественного утреннего света, и благодаря воздействию света человек естественным образом просыпается в заданное время, что позволяет избежать вреда для здоровья, который наносит резкое пробуждение от традиционного будильника." },
    { sp: "", zh: "希望这样能向真正的“自然醒”走近一点，再走近一点。", py: "Xīwàng zhèyàng néng xiàng zhēnzhèng de “zìrán xǐng” zǒujìn yìdiǎn, zài zǒujìn yìdiǎn.", ru: "Надеемся, что таким образом мы сможем немного приблизиться, а потом ещё немного приблизиться к настоящему «естественному пробуждению»." }
  ] }
],
"5.12": [
  { t: "海外用户玩儿微信 · Overseas Users of WeChat", lines: [
    { sp: "", zh: "举着手机，边颠着球边拍……国际足球明星梅西用微信直播自己的颠球技术，把手机另一头一个正在哭的小宝贝逗笑。", py: "Jǔzhe shǒujī, biān diānzhe qiú biān pāi… guójì zúqiú míngxīng Méixī yòng Wēixìn zhíbō zìjǐ de diānqiú jìshù, bǎ shǒujī lìng yì tóu yí ge zhèngzài kū de xiǎo bǎobèi dòuxiào.", ru: "Держа телефон, жонглируя мячом и одновременно снимая… международная футбольная звезда Месси через WeChat транслирует своё умение жонглировать мячом, рассмешив плачущего малыша на другом конце связи." },
    { sp: "", zh: "这条30秒的全新广告宣传片在全球15个国家和地区同步上线。", py: "Zhè tiáo sānshí miǎo de quánxīn guǎnggào xuānchuánpiàn zài quánqiú shíwǔ ge guójiā hé dìqū tóngbù shàngxiàn.", ru: "Этот совершенно новый 30-секундный рекламный ролик был одновременно выпущен в 15 странах и регионах мира." },
    { sp: "", zh: "如此大手笔的推广，腾讯自有其底气所在。", py: "Rúcǐ dà shǒubǐ de tuīguǎng, Téngxùn zì yǒu qí dǐqì suǒzài.", ru: "За таким масштабным продвижением у Tencent есть своя уверенность." },
    { sp: "", zh: "微信“在海外注册用户已经超过7000万，且在快速增长当中”。", py: "Wēixìn “zài hǎiwài zhùcè yònghù yǐjīng chāoguò qīqiān wàn, qiě zài kuàisù zēngzhǎng dāngzhōng”.", ru: "У WeChat «число зарегистрированных пользователей за рубежом уже превысило 70 миллионов и продолжает быстро расти»." },
    { sp: "", zh: "7月3日，在北京召开的2013腾讯合作伙伴大会上，腾讯总裁刘炽平言语间充满了骄傲。", py: "Qī yuè sān rì, zài Běijīng zhàokāi de èr líng yī sān Téngxùn hézuò huǒbàn dàhuì shang, Téngxùn zǒngcái Liú Chìpíng yányǔ jiān chōngmǎnle jiāo'ào.", ru: "3 июля на прошедшей в Пекине конференции партнёров Tencent 2013 года президент Tencent Лю Чипин в своих словах не скрывал гордости." },
    { sp: "", zh: "2011年1月，微信上线；同年4月，以英文名WeChat正式进入国际市场；2011年12月，实现支持全球100个国家的短信注册；2012年底，覆盖国家和地区超过100个。", py: "Èr líng yī yī nián yī yuè, Wēixìn shàngxiàn; tóngnián sì yuè, yǐ Yīngwénmíng WeChat zhèngshì jìnrù guójì shìchǎng; èr líng yī yī nián shí'èr yuè, shíxiàn zhīchí quánqiú yìbǎi ge guójiā de duǎnxìn zhùcè; èr líng yī èr nián dǐ, fùgài guójiā hé dìqū chāoguò yìbǎi ge.", ru: "В январе 2011 года WeChat был запущен; в апреле того же года он под английским названием WeChat официально вышел на международный рынок; в декабре 2011 года стала возможна регистрация по SMS уже в 100 странах мира; к концу 2012 года он охватывал более 100 стран и регионов." },
    { sp: "", zh: "如今，微信已经覆盖了200多个国家和地区、支持16种外语，是全球使用人数最多的移动通信应用。", py: "Rújīn, Wēixìn yǐjīng fùgàile liǎngbǎi duō ge guójiā hé dìqū, zhīchí shíliù zhǒng wàiyǔ, shì quánqiú shǐyòng rénshù zuì duō de yídòng tōngxìn yìngyòng.", ru: "Сегодня WeChat охватывает уже более 200 стран и регионов, поддерживает 16 иностранных языков и является мобильным коммуникационным приложением с наибольшим числом пользователей в мире." },
    { sp: "", zh: "在美国互联网企业“称霸”全球的背景下，作为中国自己的移动互联网产品，微信的出现，自然吸引了更多的关注。", py: "Zài Měiguó hùliánwǎng qǐyè “chēngbà” quánqiú de bèijǐng xià, zuòwéi Zhōngguó zìjǐ de yídòng hùliánwǎng chǎnpǐn, Wēixìn de chūxiàn, zìrán xīyǐnle gèng duō de guānzhù.", ru: "На фоне того, что американские интернет-компании «доминируют» во всём мире, появление WeChat — собственного китайского продукта мобильного интернета — естественным образом привлекло к себе повышенное внимание." },
    { sp: "", zh: "被称为“微信之父”的腾讯公司高级副总裁张小龙介绍了微信的发展过程：", py: "Bèi chēngwéi “Wēixìn zhī fù” de Téngxùn Gōngsī gāojí fù zǒngcái Zhāng Xiǎolóng jièshàole Wēixìn de fāzhǎn guòchéng:", ru: "Старший вице-президент компании Tencent Чжан Сяолун, которого называют «отцом WeChat», рассказал о процессе развития WeChat:" },
    { sp: "张小龙", zh: "微信的研究开发工作开展得很早，2010年底，移动互联网刚起步，腾讯广州产品研发中心就开始考虑相关业务。", py: "Wēixìn de yánjiū kāifā gōngzuò kāizhǎn de hěn zǎo, èr líng yī líng nián dǐ, yídòng hùliánwǎng gāng qǐbù, Téngxùn Guǎngzhōu chǎnpǐn yánfā zhōngxīn jiù kāishǐ kǎolǜ xiāngguān yèwù.", ru: "«Работа над исследованием и разработкой WeChat началась очень рано: в конце 2010 года, когда мобильный интернет только зарождался, гуанчжоуский центр разработки продуктов Tencent уже начал рассматривать соответствующее направление деятельности.»" },
    { sp: "张小龙", zh: "他们清楚地认识到了这样的现实——在个人计算机时代，由于中国互联网的用户数量以及市场成熟程度等都低于发达国家，在产品创新上难有领导地位，而移动互联网是一个重新开始的机会。", py: "Tāmen qīngchu de rènshidàole zhèyàng de xiànshí — zài gèrén jìsuànjī shídài, yóuyú Zhōngguó hùliánwǎng de yònghù shùliàng yǐjí shìchǎng chéngshú chéngdù děng dōu dīyú fādá guójiā, zài chǎnpǐn chuàngxīn shang nán yǒu lǐngdǎo dìwèi, ér yídòng hùliánwǎng shì yí ge chóngxīn kāishǐ de jīhuì.", ru: "«Мы ясно осознавали такую реальность: в эпоху персональных компьютеров, поскольку количество пользователей интернета в Китае и степень зрелости рынка отставали от развитых стран, трудно было занять лидирующую позицию в инновациях продукта, тогда как мобильный интернет — это возможность начать всё заново.»" },
    { sp: "", zh: "在经营销售上，微信针对不同的国家和地区，推出了不同的广告片，邀请当地明星和名人代言，收效相当不错。", py: "Zài jīngyíng xiāoshòu shang, Wēixìn zhēnduì bùtóng de guójiā hé dìqū, tuīchūle bùtóng de guǎnggàopiàn, yāoqǐng dāngdì míngxīng hé míngrén dàiyán, shōuxiào xiāngdāng búcuò.", ru: "В сфере продвижения и продаж WeChat выпускал разные рекламные ролики для разных стран и регионов, приглашая местных звёзд и знаменитостей сниматься в них, и результаты оказались весьма неплохими." },
    { sp: "", zh: "海外用户群中不仅有华裔和新移民，还出现了更多的外国人。", py: "Hǎiwài yònghù qún zhōng bùjǐn yǒu huáyì hé xīn yímín, hái chūxiànle gèng duō de wàiguórén.", ru: "Среди зарубежных пользователей есть не только этнические китайцы и новые иммигранты — появляется всё больше иностранцев." }
  ] }
],
"5.13": [
  { t: "锯掉生活的“筐底” · Cutting Off the “Bottom of the Basket” in Life", lines: [
    { sp: "", zh: "篮球运动是1891年由美国马萨诸塞州的体育教师詹姆士·奈史密斯博士发明的。", py: "Lánqiú yùndòng shì yī bā jiǔ yī nián yóu Měiguó Mǎsàzhūsài Zhōu de tǐyù jiàoshī Zhānmǔshì·Nàishǐmìsī bóshì fāmíng de.", ru: "Баскетбол был изобретён в 1891 году доктором Джеймсом Нейсмитом, учителем физкультуры из штата Массачусетс (США)." },
    { sp: "", zh: "那年的冬天特别冷，奈史密斯所在的训练学校缺乏在室内进行的球类比赛项目，他从当地人把球扔进桃子筐（当地产桃子，各家各户都备有装桃子的专用篮筐）的游戏中得到启发，将两只篮筐分别安装在体育馆两边看台的栏杆上。", py: "Nà nián de dōngtiān tèbié lěng, Nàishǐmìsī suǒzài de xùnliàn xuéxiào quēfá zài shìnèi jìnxíng de qiúlèi bǐsài xiàngmù, tā cóng dāngdì rén bǎ qiú rēngjìn táozi kuāng (dāngdì chǎn táozi, gè jiā gè hù dōu bèiyǒu zhuāng táozi de zhuānyòng lánkuāng) de yóuxì zhōng dédào qǐfā, jiāng liǎng zhī lánkuāng fēnbié ānzhuāng zài tǐyùguǎn liǎng biān kàntái de lángān shang.", ru: "Та зима была особенно холодной, и в тренировочной школе, где работал Нейсмит, не хватало спортивных игр с мячом, которые можно было бы проводить в помещении; вдохновившись игрой местных жителей, бросавших мяч в персиковые корзины (в тех краях выращивали персики, и в каждой семье имелись специальные корзины для их хранения), он установил две такие корзины на перилах трибун по обе стороны спортивного зала." },
    { sp: "", zh: "学生分为甲乙两队，以足球为比赛工具向篮内投，按得分多少决定输赢。", py: "Xuésheng fēnwéi jiǎ yǐ liǎng duì, yǐ zúqiú wéi bǐsài gōngjù xiàng lán nèi tóu, àn défēn duōshao juédìng shūyíng.", ru: "Студентов разделили на две команды — А и Б, — и, используя футбольный мяч как игровой снаряд, они бросали его в корзину; победа определялась по количеству набранных очков." },
    { sp: "", zh: "这项运动很快流行起来。", py: "Zhè xiàng yùndòng hěn kuài liúxíng qǐlai.", ru: "Этот вид спорта быстро стал популярным." },
    { sp: "", zh: "不过，由于栏杆上固定的是真正的筐，每当球投进时，就得有一个人踩着梯子上去把球取出来。", py: "Búguò, yóuyú lángān shang gùdìng de shì zhēnzhèng de kuāng, měi dāng qiú tóujìn shí, jiù děi yǒu yí ge rén cǎizhe tīzi shàngqu bǎ qiú qǔ chūlai.", ru: "Однако, поскольку на перилах были закреплены настоящие корзины, каждый раз, когда мяч попадал внутрь, кому-то приходилось лезть по лестнице, чтобы достать его оттуда." },
    { sp: "", zh: "这样的行为必须一再地重复，为此，比赛不得不断断续续地进行，缺少了激烈紧张的气氛，连运动员都不满意，更何况看比赛的球迷呢？", py: "Zhèyàng de xíngwéi bìxū yízài de chóngfù, wèi cǐ, bǐsài bùdébù duànduàn-xùxù de jìnxíng, quēshǎole jīliè jǐnzhāng de qìfēn, lián yùndòngyuán dōu bù mǎnyì, gèng hékuàng kàn bǐsài de qiúmí ne?", ru: "Это действие приходилось повторять снова и снова, из-за чего игра поневоле шла с перерывами, лишённая напряжённой, накалённой атмосферы; этим были недовольны даже сами спортсмены, не говоря уже о болельщиках?" },
    { sp: "", zh: "为了解决这个问题，大家纷纷出主意，想出了很多取球的办法。", py: "Wèile jiějué zhège wèntí, dàjiā fēnfēn chū zhǔyi, xiǎngchūle hěn duō qǔ qiú de bànfǎ.", ru: "Чтобы решить эту проблему, все наперебой предлагали идеи и придумали множество способов доставать мяч." },
    { sp: "", zh: "有一位工程师甚至专门制造出一种机器，在下面一拉篮筐就能把球弹出来。", py: "Yǒu yí wèi gōngchéngshī shènzhì zhuānmén zhìzào chū yì zhǒng jīqì, zài xiàmiàn yì lā lánkuāng jiù néng bǎ qiú tán chūlai.", ru: "Один инженер даже специально изготовил устройство: стоило потянуть корзину снизу, и мяч сам выскакивал наружу." },
    { sp: "", zh: "可是，这些办法都没能让比赛顺畅起来。", py: "Kěshì, zhèxiē bànfǎ dōu méi néng ràng bǐsài shùnchàng qǐlai.", ru: "Но ни один из этих способов так и не сделал игру гладкой и беспрепятственной." },
    { sp: "", zh: "几年后的一天，一个上幼儿园的小男孩跟着父亲从一群正在进行篮球比赛的人旁边经过。", py: "Jǐ nián hòu de yì tiān, yí ge shàng yòu'éryuán de xiǎo nánhái gēnzhe fùqin cóng yì qún zhèngzài jìnxíng lánqiú bǐsài de rén pángbiān jīngguò.", ru: "Спустя несколько лет однажды маленький мальчик, ходивший в детский сад, проходил вместе с отцом мимо группы людей, играющих в баскетбол." },
    { sp: "", zh: "看到大人们一次次辛苦地取球，小男孩好奇地问父亲：", py: "Kàndào dàrénmen yí cì cì xīnkǔ de qǔ qiú, xiǎo nánhái hàoqí de wèn fùqin:", ru: "Увидев, как взрослые снова и снова с трудом достают мяч, мальчик с любопытством спросил у отца:" },
    { sp: "小男孩", zh: "何必这么麻烦呢？把篮筐的底去掉不就行了吗？", py: "Hébì zhème máfan ne? Bǎ lánkuāng de dǐ qùdiào bú jiù xíng le ma?", ru: "Зачем так усложнять? Разве нельзя просто убрать дно у корзины?" },
    { sp: "", zh: "多亏了他这句话，人们如梦初醒，一位球员连忙找来一把锯子把篮筐的底锯掉。", py: "Duōkuīle tā zhè jù huà, rénmen rú mèng chū xǐng, yí wèi qiúyuán liánmáng zhǎolái yì bǎ jùzi bǎ lánkuāng de dǐ jùdiào.", ru: "Благодаря этой его фразе люди словно очнулись ото сна, и один из игроков тут же принёс пилу и отпилил дно корзины." },
    { sp: "", zh: "你瞧，困扰人们很长时间的取球问题就这样被一个小孩子解决了。", py: "Nǐ qiáo, kùnrǎo rénmen hěn cháng shíjiān de qǔ qiú wèntí jiù zhèyàng bèi yí ge xiǎo háizi jiějué le.", ru: "Вот так: проблема с доставанием мяча, мучившая людей очень долгое время, была решена одним маленьким ребёнком." },
    { sp: "", zh: "去掉篮筐的底，本是一件简单的事，可为什么那么多人都没有想到呢？", py: "Qùdiào lánkuāng de dǐ, běn shì yí jiàn jiǎndān de shì, kě wèishénme nàme duō rén dōu méiyǒu xiǎngdào ne?", ru: "Убрать дно у корзины — дело само по себе простое, но почему же столько людей об этом не подумали?" },
    { sp: "", zh: "说白了，因为我们的思维像篮球一样被篮筐的底挡在了半空中。", py: "Shuōbáile, yīnwèi wǒmen de sīwéi xiàng lánqiú yíyàng bèi lánkuāng de dǐ dǎng zài le bànkōngzhōng.", ru: "Проще говоря, потому что наше мышление, подобно баскетбольному мячу, было остановлено дном корзины на полпути." },
    { sp: "", zh: "于是，我们呆呆地去搬梯子、造机器……", py: "Yúshì, wǒmen dāidāi de qù bān tīzi, zào jīqì...", ru: "И вот мы бездумно тащим лестницу, изобретаем машины…" },
    { sp: "", zh: "其实，世界上本来就没有太复杂的事，复杂都是我们自己造成的。", py: "Qíshí, shìjiè shang běnlái jiù méiyǒu tài fùzá de shì, fùzá dōu shì wǒmen zìjǐ zàochéng de.", ru: "На самом деле в мире изначально не так уж много по-настоящему сложных вещей — сложность мы создаём себе сами." },
    { sp: "", zh: "生活仿佛篮筐，许多时候，我们需要的只不过是一把锯子，来锯掉那些阻碍我们的“筐底”。", py: "Shēnghuó fǎngfú lánkuāng, xǔduō shíhou, wǒmen xūyào de zhǐ búguò shì yì bǎ jùzi, lái jùdiào nàxiē zǔ'ài wǒmen de “kuāng dǐ”.", ru: "Жизнь подобна корзине: очень часто нам нужна лишь пила, чтобы отпилить то самое «дно корзины», которое нам мешает." }
  ] }
],
"5.14": [
  { t: "北京的四合院 · Quadrangle Courtyards in Beijing", lines: [
    { sp: "", zh: "四合院，是中国华北地区民居中的一种组合建筑形式。", py: "Sìhéyuàn, shì Zhōngguó Huáběi dìqū mínjū zhōng de yì zhǒng zǔhé jiànzhù xíngshì.", ru: "Сыхэюань — это разновидность комбинированной архитектурной формы среди гражданских жилищ северного Китая." },
    { sp: "", zh: "所谓四合，“四”指东、西、南、北四面，“合”就是四面房屋围在一起，中间形成一个方形的院子。", py: "Suǒwèi sìhé, “sì” zhǐ dōng, xī, nán, běi sì miàn, “hé” jiùshì sì miàn fángwū wéi zài yìqǐ, zhōngjiān xíngchéng yí ge fāngxíng de yuànzi.", ru: "Так называемое «сыхэ»: «сы» означает четыре стороны — восток, запад, юг и север, а «хэ» означает, что дома с четырёх сторон смыкаются вместе, образуя посередине квадратный двор." },
    { sp: "", zh: "四合院在中国汉族民居中历史最悠久，分布最广泛。", py: "Sìhéyuàn zài Zhōngguó Hànzú mínjū zhōng lìshǐ zuì yōujiǔ, fēnbù zuì guǎngfàn.", ru: "Среди жилищ китайцев-ханьцев сыхэюань обладает самой долгой историей и наиболее широко распространён." },
    { sp: "", zh: "不过，只要人们一提到四合院，便自然会想到北京四合院，这是因为传统的北京四合院都有一套固定的样式，十分具有代表性，在各种各样的四合院中，北京四合院可以代表其主要特点。", py: "Búguò, zhǐyào rénmen yì tídào sìhéyuàn, biàn zìrán huì xiǎngdào Běijīng sìhéyuàn, zhè shì yīnwèi chuántǒng de Běijīng sìhéyuàn dōu yǒu yí tào gùdìng de yàngshì, shífēn jùyǒu dàibiǎoxìng, zài gèzhǒng-gèyàng de sìhéyuàn zhōng, Běijīng sìhéyuàn kěyǐ dàibiǎo qí zhǔyào tèdiǎn.", ru: "Однако стоит людям упомянуть сыхэюань, как они естественным образом вспоминают именно пекинский сыхэюань — потому что традиционные пекинские сыхэюани имеют устойчивый, закреплённый стиль и весьма показательны: среди всевозможных сыхэюаней именно пекинский способен представлять их главные особенности." },
    { sp: "", zh: "北京有各种规模的四合院。", py: "Běijīng yǒu gè zhǒng guīmó de sìhéyuàn.", ru: "В Пекине есть сыхэюани самых разных размеров." },
    { sp: "", zh: "最简单的四合院只有一个院子，比较复杂的有两三个，而有钱人家，通常是由好几座四合院并列组成的。", py: "Zuì jiǎndān de sìhéyuàn zhǐ yǒu yí ge yuànzi, bǐjiào fùzá de yǒu liǎng-sān ge, ér yǒuqián rénjiā, tōngcháng shì yóu hǎo jǐ zuò sìhéyuàn bìngliè zǔchéng de.", ru: "Самый простой сыхэюань имеет всего один двор, более сложные — два-три, а у богатых семей двор обычно состоит из нескольких сыхэюаней, расположенных рядом друг с другом." },
    { sp: "", zh: "大门一般开在东南角或西北角，院中的北房是正房，比其他房屋的规模大，一般包括长辈的卧室和具备日常起居、接待客人等功能的客厅。", py: "Dàmén yìbān kāi zài dōngnán jiǎo huò xīběi jiǎo, yuàn zhōng de běi fáng shì zhèngfáng, bǐ qítā fángwū de guīmó dà, yìbān bāokuò zhǎngbèi de wòshì hé jùbèi rìcháng qǐjū, jiēdài kèrén děng gōngnéng de kètīng.", ru: "Главные ворота обычно располагаются в юго-восточном или северо-западном углу; северный дом во дворе — это главный дом, он больше остальных построек по размеру и, как правило, включает спальню старших членов семьи и гостиную, служащую для повседневной жизни и приёма гостей." },
    { sp: "", zh: "院子的两边是东西厢房，是晚辈们生活的地方。", py: "Yuànzi de liǎng biān shì dōngxī xiāngfáng, shì wǎnbèimen shēnghuó de dìfang.", ru: "По обе стороны двора находятся восточный и западный флигели — там живут младшие члены семьи." },
    { sp: "", zh: "在正房和厢房之间建有走廊，可以供人行走和休息。", py: "Zài zhèngfáng hé xiāngfáng zhījiān jiàn yǒu zǒuláng, kěyǐ gōng rén xíngzǒu hé xiūxi.", ru: "Между главным домом и флигелями построены крытые галереи, по которым можно ходить и отдыхать." },
    { sp: "", zh: "院子是十分理想的室外生活空间。", py: "Yuànzi shì shífēn lǐxiǎng de shìwài shēnghuó kōngjiān.", ru: "Двор — это в высшей степени идеальное пространство для жизни на открытом воздухе." },
    { sp: "", zh: "有的人家喜欢种草、养花、种竹子，有的人家则喜欢用大盆养金鱼。", py: "Yǒude rénjiā xǐhuan zhòng cǎo, yǎng huā, zhòng zhúzi, yǒude rénjiā zé xǐhuan yòng dà pén yǎng jīnyú.", ru: "Одни семьи любят сажать траву, разводить цветы, выращивать бамбук, другие же предпочитают держать в больших чанах золотых рыбок." },
    { sp: "", zh: "院子不仅拉近了人与自然的关系，也让家里人在此得到了感情的交流，对创造生活情趣起了很大作用，因而最为人们所喜爱。", py: "Yuànzi bùjǐn lājìnle rén yǔ zìrán de guānxi, yě ràng jiā li rén zài cǐ dédàole gǎnqíng de jiāoliú, duì chuàngzào shēnghuó qíngqù qǐle hěn dà zuòyòng, yīn'ér zuì wéi rénmen suǒ xǐ'ài.", ru: "Двор не только сближает человека с природой, но и даёт домочадцам возможность душевного общения; он играет большую роль в создании жизненного уюта и радости, поэтому пользуется наибольшей любовью людей." },
    { sp: "", zh: "只要关闭起大门，四合院内便形成一个封闭式的小环境。", py: "Zhǐyào guānbì qǐ dàmén, sìhéyuàn nèi biàn xíngchéng yí ge fēngbìshì de xiǎo huánjìng.", ru: "Стоит закрыть ворота — и внутри сыхэюаня образуется замкнутая небольшая среда." },
    { sp: "", zh: "住在四合院里的人不常与周围的邻居打交道。", py: "Zhù zài sìhéyuàn li de rén bù cháng yǔ zhōuwéi de línjū dǎ jiāodào.", ru: "Живущие в сыхэюане люди не часто контактируют с соседями по округе." },
    { sp: "", zh: "在小院里，一家人过着与世无争的日子，充分享受家庭的乐趣，自然有一种令人感到自在亲切的气氛。", py: "Zài xiǎo yuàn li, yìjiā rén guòzhe yǔshì-wúzhēng de rìzi, chōngfèn xiǎngshòu jiātíng de lèqù, zìrán yǒu yì zhǒng lìng rén gǎndào zìzài qīnqiè de qìfēn.", ru: "В маленьком дворике вся семья живёт спокойной жизнью, не споря с миром, в полной мере наслаждаясь семейными радостями, отчего там естественным образом царит атмосфера, вызывающая ощущение непринуждённости и теплоты." },
    { sp: "", zh: "但也有多户合住一座四合院的情况，被称为“大杂院”，住户多为普通劳动人民。", py: "Dàn yě yǒu duō hù hé zhù yí zuò sìhéyuàn de qíngkuàng, bèi chēngwéi “dàzáyuàn”, zhùhù duō wéi pǔtōng láodòng rénmín.", ru: "Но встречаются и случаи, когда в одном сыхэюане совместно проживает несколько семей — такое жильё называют «дацзаюань» («большой смешанный двор»); жильцы в нём в основном обычные трудящиеся." },
    { sp: "", zh: "邻里之间有时虽然也有矛盾，但更多时候是互帮互助，不是亲人胜过亲人，这种浓浓的情感是许多老北京人无法忘记的。", py: "Línlǐ zhījiān yǒushí suīrán yě yǒu máodùn, dàn gèng duō shíhou shì hùbāng-hùzhù, bú shì qīnrén shèngguò qīnrén, zhè zhǒng nóngnóng de qínggǎn shì xǔduō lǎo Běijīngrén wúfǎ wàngjì de.", ru: "Хотя между соседями порой случаются и конфликты, гораздо чаще они помогают друг другу — не будучи родственниками, они относятся друг к другу порой даже теплее, чем родные; это глубокое, тёплое чувство многие коренные пекинцы забыть не могут." }
  ] }
],
"5.15": [
  { t: "纸上谈兵 · Being an Armchair Strategist", lines: [
    { sp: "", zh: "两千七百多年前的战国末期，赵国名将赵奢有个儿子叫赵括，他从小读了不少兵书，跟别人谈论起军事来，没有人说得过他，就是父亲赵奢也难不住他。", py: "Liǎngqiān-qībǎi duō nián qián de Zhànguó mòqī, Zhàoguó míngjiàng Zhào Shē yǒu ge érzi jiào Zhào Kuò, tā cóngxiǎo dúle bùshǎo bīngshū, gēn biérén tánlùn qǐ jūnshì lái, méiyǒu rén shuō de guò tā, jiùshì fùqin Zhào Shē yě nánbuzhù tā.", ru: "Более двух тысяч семисот лет назад, в конце эпохи Чжаньго, у знаменитого полководца царства Чжао по имени Чжао Шэ был сын по имени Чжао Ко: с детства он прочитал немало военных трактатов, и когда заводил разговор о военном деле, никто не мог его переспорить — даже отец, Чжао Шэ, не мог поставить его в тупик." },
    { sp: "", zh: "赵括因此很骄傲，自以为天下无敌，连父亲也不放在眼里。", py: "Zhào Kuò yīncǐ hěn jiāo'ào, zì yǐwéi tiānxià wúdí, lián fùqin yě bú fàng zài yǎnli.", ru: "Из-за этого Чжао Ко был очень горделив, считал себя непобедимым во всей Поднебесной и даже отца ни во что не ставил." },
    { sp: "", zh: "但是赵奢心里明白，自己的儿子虽然对军事理论都很了解，但是没有实际作战的经验，想法很不符合实际。", py: "Dànshì Zhào Shē xīnli míngbai, zìjǐ de érzi suīrán duì jūnshì lǐlùn dōu hěn liǎojiě, dànshì méiyǒu shíjì zuòzhàn de jīngyàn, xiǎngfǎ hěn bù fúhé shíjì.", ru: "Но в душе Чжао Шэ понимал: хотя его сын прекрасно разбирался в военной теории, у него не было опыта настоящих боевых действий, и его представления совсем не соответствовали действительности." },
    { sp: "", zh: "他曾经偷偷对妻子说：", py: "Tā céngjīng tōutōu duì qīzi shuō:", ru: "Он однажды тайком сказал жене:" },
    { sp: "赵奢", zh: "儿子的毛病是只会讲大道理，缺乏实际锻炼，不能当大将。", py: "Érzi de máobìng shì zhǐ huì jiǎng dà dàolǐ, quēfá shíjì duànliàn, bù néng dāng dàjiàng.", ru: "Недостаток нашего сына в том, что он умеет только рассуждать о высоких истинах, ему не хватает практической закалки, — он не может быть полководцем." },
    { sp: "赵奢", zh: "如果让他当了大将，迟早会害了赵国。", py: "Rúguǒ ràng tā dāngle dàjiàng, chízǎo huì hàile Zhàoguó.", ru: "Если позволить ему стать полководцем, он рано или поздно погубит царство Чжао." },
    { sp: "", zh: "几年后，赵奢去世了。", py: "Jǐ nián hòu, Zhào Shē qùshì le.", ru: "Несколько лет спустя Чжао Шэ скончался." },
    { sp: "", zh: "这一年正好秦国军队来打赵国，赵国派老将廉颇带20万大军迎战。", py: "Zhè yì nián zhènghǎo Qínguó jūnduì lái dǎ Zhàoguó, Zhàoguó pài lǎojiàng Lián Pō dài èrshí wàn dàjūn yíngzhàn.", ru: "В том же году как раз войска царства Цинь пошли войной на Чжао, и царство Чжао отправило старого полководца Лянь По с двухсоттысячным войском навстречу врагу." },
    { sp: "", zh: "廉颇根据敌强我弱的形势，命令士兵们坚守阵地，绝对不可主动出战。", py: "Lián Pō gēnjù dí qiáng wǒ ruò de xíngshì, mìnglìng shìbīngmen jiānshǒu zhèndì, juéduì bùkě zhǔdòng chūzhàn.", ru: "Лянь По, учитывая обстановку — противник силён, а мы слабы, — приказал солдатам во что бы то ни стало удерживать позиции и ни в коем случае не вступать в бой первыми." },
    { sp: "", zh: "秦军多次挑战，骂他是胆小鬼，他还是不出兵。", py: "Qínjūn duō cì tiǎozhàn, mà tā shì dǎnxiǎoguǐ, tā háishi bù chūbīng.", ru: "Циньские войска много раз бросали ему вызов, обзывали его трусом, но он всё равно не выводил войска в бой." },
    { sp: "", zh: "这个办法果然非常有效，成功地把秦军拦在了国门之外。", py: "Zhège bànfǎ guǒrán fēicháng yǒuxiào, chénggōng de bǎ Qínjūn lán zài le guómén zhī wài.", ru: "Этот способ действительно оказался очень эффективным и успешно удержал циньские войска за пределами границ царства." },
    { sp: "", zh: "渐渐地，秦军无法快速取得胜利，粮食也快没了，有些坚持不住了。", py: "Jiànjiàn de, Qínjūn wúfǎ kuàisù qǔdé shènglì, liángshi yě kuài méi le, yǒuxiē jiānchí bú zhù le.", ru: "Постепенно циньские войска оказались не в состоянии быстро одержать победу, провизия у них тоже подходила к концу, и некоторые уже не могли больше держаться." },
    { sp: "", zh: "秦人深知廉颇善于用兵，如果想在短期内打败赵国，必须想办法叫赵国把廉颇调回去。", py: "Qínrén shēnzhī Lián Pō shànyú yòngbīng, rúguǒ xiǎng zài duǎnqī nèi dǎbài Zhàoguó, bìxū xiǎng bànfǎ jiào Zhàoguó bǎ Lián Pō diào huíqu.", ru: "Циньцы прекрасно знали, что Лянь По искусен в военном деле, и понимали: если они хотят разгромить Чжао в короткий срок, им нужно найти способ заставить Чжао отозвать Лянь По." },
    { sp: "", zh: "于是，他们在赵国四处散布谣言，说秦军最怕赵括，别的人都不放在眼里。", py: "Yúshì, tāmen zài Zhàoguó sìchù sànbù yáoyán, shuō Qínjūn zuì pà Zhào Kuò, biéde rén dōu bú fàng zài yǎnli.", ru: "Поэтому они повсюду в царстве Чжао распустили слух, что циньские войска больше всего боятся Чжао Ко, а на остальных им и вовсе наплевать." },
    { sp: "", zh: "这时，赵王正因廉颇闭门不战而生气呢，听到外面的那些谣言，果然上当了，他派赵括去换回廉颇。", py: "Zhè shí, Zhàowáng zhèng yīn Lián Pō bìmén bú zhàn ér shēngqì ne, tīngdào wàimiàn de nàxiē yáoyán, guǒrán shàngdàng le, tā pài Zhào Kuò qù huànhuí Lián Pō.", ru: "В это время чжаоский ван как раз злился на Лянь По за то, что тот заперся и не вступал в бой; услышав эти слухи, он и вправду попался на удочку и отправил Чжао Ко сменить Лянь По." },
    { sp: "", zh: "赵括的母亲再三阻止赵王任命儿子为大将，说他还没有独立带兵作战的资格。", py: "Zhào Kuò de mǔqin zàisān zǔzhǐ Zhàowáng rènmìng érzi wéi dàjiàng, shuō tā hái méiyǒu dúlì dàibīng zuòzhàn de zīgé.", ru: "Мать Чжао Ко снова и снова пыталась отговорить чжаоского вана от назначения сына полководцем, говоря, что у него ещё нет квалификации, чтобы самостоятельно командовать войском в бою." },
    { sp: "", zh: "可是，糊涂的赵王哪里听得进去！", py: "Kěshì, hútu de Zhàowáng nǎli tīng de jìnqu!", ru: "Но разве мог недалёкий чжаоский ван прислушаться к этому!" },
    { sp: "", zh: "公元前260年，赵括带兵出战。", py: "Gōngyuán qián èrbǎi-liùshí nián, Zhào Kuò dài bīng chūzhàn.", ru: "В 260 году до н.э. Чжао Ко повёл войско в бой." },
    { sp: "", zh: "一直盲目自信、轻视秦军的他完全改变了廉颇的作战方案，死搬兵书上的理论，主动进攻秦军，结果数十万赵军全部被杀，丢掉了宝贵的生命。", py: "Yìzhí mángmù zìxìn, qīngshì Qínjūn de tā wánquán gǎibiànle Lián Pō de zuòzhàn fāng'àn, sǐbān bīngshū shang de lǐlùn, zhǔdòng jìngōng Qínjūn, jiéguǒ shù shí wàn Zhàojūn quánbù bèi shā, diūdiàole bǎoguì de shēngmìng.", ru: "Слепо самоуверенный и презиравший циньское войско, он полностью изменил план сражения Лянь По, механически применил книжные теории, сам первым напал на циньцев, в результате чего несколько сотен тысяч чжаоских солдат были полностью перебиты, потеряв драгоценные жизни." },
    { sp: "", zh: "这就是成语“纸上谈兵”的故事。", py: "Zhè jiùshì chéngyǔ “zhǐshàng-tánbīng” de gùshi.", ru: "Это и есть история идиомы «纸上谈兵» — «вести войну на бумаге» (пустое теоретизирование)." },
    { sp: "", zh: "现在常用这个成语讽刺那些只会空谈理论的人，提醒大家做事一定要灵活，要注意理论联系实际。", py: "Xiànzài cháng yòng zhège chéngyǔ fěngcì nàxiē zhǐ huì kōngtán lǐlùn de rén, tíxǐng dàjiā zuò shì yídìng yào línghuó, yào zhùyì lǐlùn liánxì shíjì.", ru: "Сейчас этой идиомой обычно высмеивают тех, кто способен лишь пустословить о теории, напоминая всем, что в делах нужно быть гибким и увязывать теорию с практикой." }
  ] }
],
"5.16": [
  { t: "体重与节食 · Weight and Diet", lines: [
    { sp: "", zh: "据报道，医学专家进行了一项新研究，研究发现：由于人们在一周内的营养摄入和饮食模式会影响到他们的体重变化，因此节食者的体重会在一周内上下波动。", py: "Jù bàodào, yīxué zhuānjiā jìnxíngle yí xiàng xīn yánjiū, yánjiū fāxiàn: yóuyú rénmen zài yì zhōu nèi de yíngyǎng shèrù hé yǐnshí móshì huì yǐngxiǎng dào tāmen de tǐzhòng biànhuà, yīncǐ jiéshízhě de tǐzhòng huì zài yì zhōu nèi shàngxià bōdòng.", ru: "Как сообщается, медицинские эксперты провели новое исследование и обнаружили: поскольку потребление питательных веществ и режим питания в течение недели влияют на изменение веса человека, вес тех, кто сидит на диете, колеблется вверх-вниз в течение недели." },
    { sp: "", zh: "总共有80名年龄在25-62岁之间的成年人参与了这项研究。", py: "Zǒnggòng yǒu bāshí míng niánlíng zài èrshíwǔ zhì liùshí'èr suì zhī jiān de chéngnián rén cānyùle zhè xiàng yánjiū.", ru: "В общей сложности в этом исследовании приняли участие 80 взрослых в возрасте от 25 до 62 лет." },
    { sp: "", zh: "研究人员根据他们的相对体重变化将其分为三种类型：体重减轻者、体重增加者和体重保持者。", py: "Yánjiū rényuán gēnjù tāmen de xiāngduì tǐzhòng biànhuà jiāng qí fēnwéi sān zhǒng lèixíng: tǐzhòng jiǎnqīng zhě, tǐzhòng zēngjiā zhě hé tǐzhòng bǎochí zhě.", ru: "Исследователи, исходя из относительных изменений их веса, разделили участников на три типа: те, у кого вес снижался, те, у кого вес увеличивался, и те, чей вес оставался стабильным." },
    { sp: "", zh: "这些成年人在每天起床之后、早餐之前称一下自己的体重，为了保证可靠性，只有那些至少连续7天以上称过体重的人才会被纳入分析。", py: "Zhèxiē chéngnián rén zài měitiān qǐchuáng zhīhòu, zǎocān zhīqián chēng yíxià zìjǐ de tǐzhòng, wèile bǎozhèng kěkàoxìng, zhǐyǒu nàxiē zhìshǎo liánxù qī tiān yǐshàng chēngguo tǐzhòng de rén cái huì bèi nàrù fēnxī.", ru: "Эти взрослые каждый день после пробуждения и перед завтраком взвешивались; чтобы обеспечить достоверность данных, в анализ включали только тех, кто взвешивался не менее семи дней подряд." },
    { sp: "", zh: "对这些志愿者的跟踪调查时间最短为15天，最长为330天。", py: "Duì zhèxiē zhìyuànzhě de gēnzōng diàochá shíjiān zuì duǎn wéi shíwǔ tiān, zuì cháng wéi sānbǎi-sānshí tiān.", ru: "Продолжительность наблюдения за этими добровольцами составляла от 15 дней минимум до 330 дней максимум." },
    { sp: "", zh: "研究成果显示：这些人的体重变化表现出清晰的模式，即周末之后体重升高，在工作日体重减轻（周五达到最低点）。", py: "Yánjiū chéngguǒ xiǎnshì: zhèxiē rén de tǐzhòng biànhuà biǎoxiàn chū qīngxī de móshì, jí zhōumò zhīhòu tǐzhòng shēnggāo, zài gōngzuòrì tǐzhòng jiǎnqīng (zhōuwǔ dádào zuì dī diǎn).", ru: "Результаты исследования показали: изменения веса этих людей демонстрируют чёткую закономерность, а именно: после выходных вес повышается, а в рабочие дни снижается (достигая минимума в пятницу)." },
    { sp: "", zh: "研究人员还意外地发现，体重减轻者和体重增加者在体重波动模式上存在着明显不同。", py: "Yánjiū rényuán hái yìwài de fāxiàn, tǐzhòng jiǎnqīng zhě hé tǐzhòng zēngjiā zhě zài tǐzhòng bōdòng móshì shang cúnzàizhe míngxiǎn bùtóng.", ru: "Исследователи также неожиданно обнаружили, что между теми, у кого вес снижался, и теми, у кого он увеличивался, есть явное различие в характере колебаний веса." },
    { sp: "", zh: "体重减轻者会表现出较强的补偿模式，即在周末之后体重立即下降，这一下降趋势直至周五结束；而体重增加者每天的体重都会存在差异，他们在工作日的体重并无明显减轻。", py: "Tǐzhòng jiǎnqīng zhě huì biǎoxiàn chū jiào qiáng de bǔcháng móshì, jí zài zhōumò zhīhòu tǐzhòng lìjí xiàjiàng, zhè yī xiàjiàng qūshì zhízhì zhōuwǔ jiéshù; ér tǐzhòng zēngjiā zhě měitiān de tǐzhòng dōu huì cúnzài chāyì, tāmen zài gōngzuòrì de tǐzhòng bìng wú míngxiǎn jiǎnqīng.", ru: "У тех, чей вес снижался, проявлялась довольно выраженная компенсаторная модель: сразу после выходных вес немедленно начинал падать, и эта тенденция к снижению продолжалась вплоть до пятницы; у тех же, чей вес увеличивался, вес каждый день немного различался, и в рабочие дни их вес заметно не снижался." },
    { sp: "", zh: "这项联合多所医学院校所做的研究发现，除了个别人以外，多数人体重的增加会从周六开始，而体重减轻则会从周二开始，特别是对于那些体重减轻者和体重保持者来说更是如此。", py: "Zhè xiàng liánhé duō suǒ yīxué yuànxiào suǒ zuò de yánjiū fāxiàn, chúle gèbié rén yǐwài, duōshù rén tǐzhòng de zēngjiā huì cóng zhōuliù kāishǐ, ér tǐzhòng jiǎnqīng zé huì cóng zhōu'èr kāishǐ, tèbié shì duìyú nàxiē tǐzhòng jiǎnqīng zhě hé tǐzhòng bǎochí zhě láishuō gèng shì rúcǐ.", ru: "Это исследование, проведённое совместно несколькими медицинскими вузами, обнаружило, что, за редким исключением, у большинства людей увеличение веса начинается с субботы, а снижение веса — со вторника, и это особенно верно для тех, чей вес снижается или остаётся стабильным." },
    { sp: "", zh: "它表明人们的体重变化在一周内会显示出一种明显的规律，工作日和周末体重的临时变化应该被视为正常现象，而非真正的体重增加，这是由于人们在周末会有更多的时间外出就餐。", py: "Tā biǎomíng rénmen de tǐzhòng biànhuà zài yì zhōu nèi huì xiǎnshì chū yì zhǒng míngxiǎn de guīlǜ, gōngzuòrì hé zhōumò tǐzhòng de línshí biànhuà yīnggāi bèi shìwéi zhèngcháng xiànxiàng, ér fēi zhēnzhèng de tǐzhòng zēngjiā, zhè shì yóuyú rénmen zài zhōumò huì yǒu gèng duō de shíjiān wàichū jiùcān.", ru: "Это показывает, что изменения веса людей в течение недели демонстрируют явную закономерность; временные колебания веса в будни и выходные следует считать нормальным явлением, а не настоящим увеличением веса, — это связано с тем, что на выходных у людей больше времени, чтобы поесть вне дома." },
    { sp: "", zh: "周末对饮食稍微有些放纵影响不大，但为了能成功减轻体重，想要变苗条的节食者应注意到这种变化规律，周末之后不要再找任何吃美食的借口，应及时采取措施阻止这一上升趋势。", py: "Zhōumò duì yǐnshí shāowēi yǒuxiē fàngzòng yǐngxiǎng bú dà, dàn wèile néng chénggōng jiǎnqīng tǐzhòng, xiǎng yào biàn miáotiao de jiéshízhě yīng zhùyìdào zhè zhǒng biànhuà guīlǜ, zhōumò zhīhòu búyào zài zhǎo rènhé chī měishí de jièkǒu, yīng jíshí cǎiqǔ cuòshī zǔzhǐ zhè yī shàngshēng qūshì.", ru: "Небольшое послабление в питании по выходным не оказывает большого влияния, но чтобы успешно сбросить вес, желающим похудеть сидящим на диете следует обратить внимание на эту закономерность: после выходных не стоит больше искать предлогов, чтобы полакомиться вкусной едой, а нужно вовремя принять меры, чтобы остановить эту восходящую тенденцию." }
  ] }
],
"5.17": [
  { t: "在最美好的时刻离开 · Ending at the Best Moment", lines: [
    { sp: "", zh: "我奶奶说过：", py: "Wǒ nǎinai shuōguo:", ru: "Моя бабушка когда-то сказала:" },
    { sp: "奶奶", zh: "人们应该在最美好的时候离开。", py: "Rénmen yīnggāi zài zuì měihǎo de shíhou líkāi.", ru: "Люди должны уходить в самый прекрасный момент." },
    { sp: "", zh: "因为这个认知而获得诺贝尔奖的，不是我奶奶，而是心理学家丹尼尔·卡内曼。", py: "Yīnwèi zhège rènzhī ér huòdé Nuòbèi'ěr Jiǎng de, bú shì wǒ nǎinai, ér shì xīnlǐxuéjiā Dānní'ěr·Kǎnèimàn.", ru: "Но Нобелевскую премию за это открытие получила не моя бабушка, а психолог Даниэль Канеман." },
    { sp: "", zh: "他将这一现象命名为“峰终定律”：我们对事物的记忆仅在高峰和结尾，而事情的经过对记忆几乎没有影响。", py: "Tā jiāng zhè yī xiànxiàng mìngmíng wéi “fēngzhōng dìnglǜ”: wǒmen duì shìwù de jìyì jǐn zài gāofēng hé jiéwěi, ér shìqing de jīngguò duì jìyì jīhū méiyǒu yǐngxiǎng.", ru: "Он назвал это явление «правилом пика и завершения»: наша память о событии сохраняется в основном лишь о его пике и о его концовке, а сам ход событий почти не влияет на память." },
    { sp: "", zh: "高峰之后，终点出现得越迅速，这件事留给我们的印象就越深刻。", py: "Gāofēng zhīhòu, zhōngdiǎn chūxiàn de yuè xùnsù, zhè jiàn shì liú gěi wǒmen de yìnxiàng jiù yuè shēnkè.", ru: "Чем быстрее наступает конец после пика, тем более глубокое впечатление это событие оставляет у нас." },
    { sp: "", zh: "大部分人不理解这一定律。", py: "Dà bùfen rén bù lǐjiě zhè yī dìnglǜ.", ru: "Большинство людей не понимают этого закона." },
    { sp: "", zh: "比如说为了一场戏剧演出，我们会投入很多时间，准备服装、化妆、道具、舞台美术，以创造良好的效果，争取给观众留下一个好的印象，却常常忽视结束退场时的准备。", py: "Bǐrú shuō wèile yì chǎng xìjù yǎnchū, wǒmen huì tóurù hěn duō shíjiān, zhǔnbèi fúzhuāng, huàzhuāng, dàojù, wǔtái měishù, yǐ chuàngzào liánghǎo de xiàoguǒ, zhēngqǔ gěi guānzhòng liúxià yí ge hǎo de yìnxiàng, què chángcháng hūshì jiéshù tuìchǎng shí de zhǔnbèi.", ru: "Например, ради театральной постановки мы вкладываем много времени, готовим костюмы, грим, реквизит, сценическое оформление, чтобы добиться хорошего эффекта и оставить у зрителей хорошее впечатление, но при этом часто пренебрегаем подготовкой к завершению и уходу со сцены." },
    { sp: "", zh: "演出开始时人们认为很有魅力，但是糟糕的结局会给人留下难以忘记的坏印象。", py: "Yǎnchū kāishǐ shí rénmen rènwéi hěn yǒu mèilì, dànshì zāogāo de jiéjú huì gěi rén liúxià nányǐ wàngjì de huài yìnxiàng.", ru: "В начале спектакля люди считают его очень привлекательным, но неудачная концовка оставляет у зрителей незабываемое плохое впечатление." },
    { sp: "", zh: "有一次，我去参加一个婚礼，前三个小时感觉都很好，只在最后一个小时感到无聊。", py: "Yǒu yí cì, wǒ qù cānjiā yí ge hūnlǐ, qián sān ge xiǎoshí gǎnjué dōu hěn hǎo, zhǐ zài zuìhòu yí ge xiǎoshí gǎndào wúliáo.", ru: "Однажды я пошёл на свадьбу: первые три часа всё было замечательно, и только в последний час мне стало скучно." },
    { sp: "", zh: "三个小时快乐减一个小时无聊等于两个小时快乐，也就是说，我愉快地度过了两个小时。", py: "Sān ge xiǎoshí kuàilè jiǎn yí ge xiǎoshí wúliáo děngyú liǎng ge xiǎoshí kuàilè, yě jiùshì shuō, wǒ yúkuài de dùguòle liǎng ge xiǎoshí.", ru: "Три часа радости минус один час скуки равно два часа радости, то есть, иначе говоря, я приятно провёл два часа." },
    { sp: "", zh: "但是，我的记忆并不是这样计算的。", py: "Dànshì, wǒ de jìyì bìng bú shì zhèyàng jìsuàn de.", ru: "Однако моя память считает совсем не так." },
    { sp: "", zh: "如果我参加另外一次活动，只在那里待一个小时，早早地告别，我却享受了满满60分钟的快乐。", py: "Rúguǒ wǒ cānjiā lìngwài yí cì huódòng, zhǐ zài nàli dāi yí ge xiǎoshí, zǎozǎo de gàobié, wǒ què xiǎngshòule mǎnmǎn liùshí fēnzhōng de kuàilè.", ru: "Если бы я пошёл на другое мероприятие, пробыл там всего один час и рано попрощался, я бы насладился целыми и полными 60 минутами радости." },
    { sp: "", zh: "与第一次相比，第二次的聚会留给我的印象更为美好。", py: "Yǔ dì-yī cì xiāngbǐ, dì-èr cì de jùhuì liú gěi wǒ de yìnxiàng gèng wéi měihǎo.", ru: "По сравнению с первым разом, вторая встреча оставила бы у меня ещё более прекрасное впечатление." },
    { sp: "", zh: "看电影也是如此。", py: "Kàn diànyǐng yě shì rúcǐ.", ru: "С просмотром фильмов дело обстоит так же." },
    { sp: "", zh: "一部电影，开始虽然剧情平平常常，如果最后半个小时能使我们感动，我们依然会向别人推荐它。", py: "Yí bù diànyǐng, kāishǐ suīrán jùqíng píngpíng-chángcháng, rúguǒ zuìhòu bàn ge xiǎoshí néng shǐ wǒmen gǎndòng, wǒmen yīrán huì xiàng biérén tuījiàn tā.", ru: "Если фильм в начале имеет самый обычный сюжет, но последние полчаса трогают нас до глубины души, мы всё равно будем рекомендовать его другим." },
    { sp: "", zh: "相反，如果在前半个小时就把剧情的创造力表现得淋漓尽致，结尾却非常普通，那么，观众对这部电影的评价就肯定不好，甚至会说这是一部“烂片”。", py: "Xiāngfǎn, rúguǒ zài qián bàn ge xiǎoshí jiù bǎ jùqíng de chuàngzàolì biǎoxiàn de línlí jìnzhì, jiéwěi què fēicháng pǔtōng, nàme, guānzhòng duì zhè bù diànyǐng de píngjià jiù kěndìng bù hǎo, shènzhì huì shuō zhè shì yí bù “lànpiàn”.", ru: "И наоборот, если в первые полчаса творческий потенциал сюжета раскрыт в полной мере, а концовка при этом самая заурядная, то оценка зрителей у этого фильма непременно окажется плохой, и они даже назовут его «отстойным фильмом»." },
    { sp: "", zh: "作为电视节目主持人，我在工作中常常会运用“峰终定律”。", py: "Zuòwéi diànshì jiémù zhǔchírén, wǒ zài gōngzuò zhōng chángcháng huì yùnyòng “fēngzhōng dìnglǜ”.", ru: "Как ведущий телевизионных программ, я в своей работе часто применяю «правило пика и завершения»." },
    { sp: "", zh: "例如，做节目时，与开幕式相比，我们宁可把更多的精力集中在闭幕式上，这样可以加强观众对节目的印象。", py: "Lìrú, zuò jiémù shí, yǔ kāimùshì xiāngbǐ, wǒmen nìngkě bǎ gèng duō de jīnglì jízhōng zài bìmùshì shang, zhèyàng kěyǐ jiāqiáng guānzhòng duì jiémù de yìnxiàng.", ru: "Например, работая над программой, мы, по сравнению с церемонией открытия, скорее сосредоточим больше усилий на церемонии закрытия — так можно усилить впечатление зрителей о программе." },
    { sp: "", zh: "虽然很多人并不了解“峰终定律”，但是，他们能从经验中体会这种做法的重要性。", py: "Suīrán hěn duō rén bìng bù liǎojiě “fēngzhōng dìnglǜ”, dànshì, tāmen néng cóng jīngyàn zhōng tǐhuì zhè zhǒng zuòfǎ de zhòngyàoxìng.", ru: "Хотя многие люди вовсе не знакомы с «правилом пика и завершения», они всё же способны на собственном опыте прочувствовать важность такого подхода." }
  ] }
],
"5.18": [
  { t: "抽象艺术美不美 · Abstract Art: Beautiful or Not?", lines: [
    { sp: "", zh: "对有些人来说，抽象艺术没有古典艺术那么容易欣赏，画布上那些不规则的色块、线条，实在看不出有什么意义。", py: "Duì yǒuxiē rén láishuō, chōuxiàng yìshù méiyǒu gǔdiǎn yìshù nàme róngyì xīnshǎng, huàbù shang nàxiē bù guīzé de sèkuài, xiàntiáo, shízài kàn bu chū yǒu shénme yìyì.", ru: "Для некоторых людей абстрактное искусство не так легко воспринимать, как классическое: неправильной формы цветовые пятна и линии на холсте кажутся совершенно бессмысленными." },
    { sp: "", zh: "抽象派画家的作品中经常见到好像随便洒上颜料而形成的画作，在有人看来极其神秘甚至丑陋，有人却从中感受到对自由、对生命的赞美。", py: "Chōuxiàngpài huàjiā de zuòpǐn zhōng chángcháng jiàndào hǎoxiàng suíbiàn sǎshàng yánliào ér xíngchéng de huàzuò, zài yǒurén kàn lái jíqí shénmì shènzhì chǒulòu, yǒurén què cóngzhōng gǎnshòu dào duì zìyóu, duì shēngmìng de zànměi.", ru: "В работах художников-абстракционистов часто встречаются картины, будто бы образованные краской, разбрызганной как попало; одним они кажутся крайне таинственными и даже уродливыми, а другие видят в них восхваление свободы и жизни." },
    { sp: "", zh: "研究者设计了一个有趣的实验。", py: "Yánjiūzhě shèjìle yí ge yǒuqù de shíyàn.", ru: "Исследователи разработали интересный эксперимент." },
    { sp: "", zh: "志愿者的任务很简单，每个人会看到两两一组出现的一些图画，每组中一幅出自著名抽象艺术家之手，另一幅是业余爱好者、婴儿、黑猩猩或者大象的涂鸦。", py: "Zhìyuànzhě de rènwu hěn jiǎndān, měi ge rén huì kàndào liǎngliǎng yì zǔ chūxiàn de yìxiē túhuà, měi zǔ zhōng yì fú chūzì zhùmíng chōuxiàng yìshùjiā zhī shǒu, lìng yì fú shì yèyú àihàozhě, yīng'ér, hēixīngxing huòzhě dàxiàng de túyā.", ru: "Задание для добровольцев было простым: каждый видел несколько картин, показанных парами, причём в каждой паре одна была написана рукой известного художника-абстракциониста, а вторая представляла собой мазню любителя, младенца, шимпанзе или слона." },
    { sp: "", zh: "志愿者必须判断每一组画作中自己更喜欢哪一幅。", py: "Zhìyuànzhě bìxū pànduàn měi yì zǔ huàzuò zhōng zìjǐ gèng xǐhuan nǎ yì fú.", ru: "Добровольцы должны были в каждой паре картин определить, какая из них им больше нравится." },
    { sp: "", zh: "其中三分之一的画作作者没有签名，而其余的则标明了身份。", py: "Qízhōng sān fēn zhī yī de huàzuò zuòzhě méiyǒu qiānmíng, ér qíyú de zé biāomíngle shēnfèn.", ru: "У трети картин авторская подпись отсутствовала, а на остальных, наоборот, была указана личность автора." },
    { sp: "", zh: "令人头疼的是，一些签名被故意弄错了，志愿者无法确认作者到底是谁，所以有可能志愿者认为自己看到的是黑猩猩的随手涂鸦，实际则是著名抽象艺术家的大作。", py: "Lìng rén tóuténg de shì, yìxiē qiānmíng bèi gùyì nòngcuò le, zhìyuànzhě wúfǎ quèrèn zuòzhě dàodǐ shì shéi, suǒyǐ yǒu kěnéng zhìyuànzhě rènwéi zìjǐ kàndào de shì hēixīngxing de suíshǒu túyā, shíjì zé shì zhùmíng chōuxiàng yìshùjiā de dàzuò.", ru: "Больше всего сбивало с толку то, что некоторые подписи специально были перепутаны, и добровольцы не могли достоверно определить, кто же автор, — поэтому вполне могло оказаться, что доброволец считал увиденное небрежной мазнёй шимпанзе, тогда как на самом деле это было выдающееся творение знаменитого художника-абстракциониста." },
    { sp: "", zh: "也许有人认为，在这种情况下根本不可能分辨出来。", py: "Yěxǔ yǒurén rènwéi, zài zhè zhǒng qíngkuàng xià gēnběn bù kěnéng fēnbiàn chūlai.", ru: "Возможно, кто-то подумает, что в такой ситуации отличить одно от другого просто невозможно." },
    { sp: "", zh: "然而在每一次测试中，志愿者普遍更喜欢的作品都是由人类艺术家挥笔完成的。", py: "Rán'ér zài měi yí cì cèshì zhōng, zhìyuànzhě pǔbiàn gèng xǐhuan de zuòpǐn dōu shì yóu rénlèi yìshùjiā huībǐ wánchéng de.", ru: "Однако в каждом испытании работы, которые в целом больше нравились добровольцам, неизменно оказывались написанными кистью художника-человека." },
    { sp: "", zh: "由此可见，志愿者能够从画作中感知艺术家的用心，哪怕他们不能够解释原因。", py: "Yóu cǐ kějiàn, zhìyuànzhě nénggòu cóng huàzuò zhōng gǎnzhī yìshùjiā de yòngxīn, nǎpà tāmen bù nénggòu jiěshì yuányīn.", ru: "Отсюда видно, что добровольцы способны почувствовать в картине вложенный художником труд и замысел, даже если они не могут объяснить причину этого." },
    { sp: "", zh: "另一个实验是这样，志愿者同时欣赏原作和画面元素被调整后的画作，包括静物画和抽象画。", py: "Lìng yí ge shíyàn shì zhèyàng, zhìyuànzhě tóngshí xīnshǎng yuánzuò hé huàmiàn yuánsù bèi tiáozhěng hòu de huàzuò, bāokuò jìngwùhuà hé chōuxiànghuà.", ru: "Другой эксперимент был устроен так: добровольцы одновременно рассматривали оригиналы картин и версии с изменёнными элементами композиции, включая натюрморты и абстрактные картины." },
    { sp: "", zh: "结果，几乎每个人都更喜欢原作。", py: "Jiéguǒ, jīhū měi ge rén dōu gèng xǐhuan yuánzuò.", ru: "В результате почти все предпочитали оригиналы." },
    { sp: "", zh: "研究者发现，当看到画上物体位置变化后，大脑中有关含意和解释的区域活跃性下降了。", py: "Yánjiūzhě fāxiàn, dāng kàndào huà shang wùtǐ wèizhì biànhuà hòu, dànǎo zhōng yǒuguān hányì hé jiěshì de qūyù huóyuèxìng xiàjiàng le.", ru: "Исследователи обнаружили, что после того, как испытуемые видели изменение положения предметов на картине, активность зон мозга, отвечающих за смысл и интерпретацию, снижалась." },
    { sp: "", zh: "这表明，我们的大脑注意到了原作的布局，并且可以感知其背后的用意，即使我们还没有清楚地感受到这个事实。", py: "Zhè biǎomíng, wǒmen de dànǎo zhùyìdàole yuánzuò de bùjú, bìngqiě kěyǐ gǎnzhī qí bèihòu de yòngyì, jíshǐ wǒmen hái méiyǒu qīngchu de gǎnshòudào zhège shìshí.", ru: "Это показывает, что наш мозг замечает композицию оригинала и способен уловить скрытый за ней замысел, даже если мы ещё не осознаём этот факт отчётливо." },
    { sp: "", zh: "至少目前可以这么说，没有证据表明黑猩猩或儿童可以这样做。", py: "Zhìshǎo mùqián kěyǐ zhème shuō, méiyǒu zhèngjù biǎomíng hēixīngxing huò értóng kěyǐ zhèyàng zuò.", ru: "По крайней мере, на данный момент можно утверждать: нет доказательств того, что шимпанзе или дети способны на подобное." },
    { sp: "", zh: "我们的大脑究竟如何感知抽象艺术，是一个有趣的话题。", py: "Wǒmen de dànǎo jiūjìng rúhé gǎnzhī chōuxiàng yìshù, shì yí ge yǒuqù de huàtí.", ru: "Каким же образом наш мозг воспринимает абстрактное искусство — это интересная тема." },
    { sp: "", zh: "每个人对抽象艺术可以有不同的解读，这既是挑战，也是自由。", py: "Měi ge rén duì chōuxiàng yìshù kěyǐ yǒu bùtóng de jiědú, zhè jì shì tiǎozhàn, yě shì zìyóu.", ru: "У каждого человека может быть своя трактовка абстрактного искусства — в этом одновременно и вызов, и свобода." }
  ] }
]
  };

